// Curated recipes from TheMealDB (https://www.themealdb.com), picked for cheap, common, overlapping ingredients.
// Generated - allergens, diet, time, cost, base and tags are estimated from the ingredients and method.
export const RECIPES = [{"id":"mdb-52770","title":"Spaghetti Bolognese","image":"https://www.themealdb.com/images/media/meals/sutysw1468247559.jpg","desc":"Italian · Beef","category":"Beef","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy","fish"],"base":"pasta","ingredients":[{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""},{"name":"minced beef","qty":500,"unit":"g","cat":"meat","text":""},{"name":"mushroom","qty":90,"unit":"g","cat":"veg","text":""},{"name":"dried oregano","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"tomato","qty":400,"unit":"g","cat":"veg","text":""},{"name":"beef stock","qty":300,"unit":"ml","cat":"pantry","text":""},{"name":"tomato purée","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"worcestershire sauce","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"spaghetti","qty":350,"unit":"g","cat":"pantry","text":""},{"name":"parmesan","qty":0,"unit":"","cat":"dairy","text":"Topping"}],"steps":["Put the onion and oil in a large pan and fry over a fairly high heat for 3-4 mins. Add the garlic and mince and fry until they both brown. Add the mushrooms and herbs, and cook for another couple of mins.","Stir in the tomatoes, beef stock, tomato ketchup or purée, Worcestershire sauce and seasoning. Bring to the boil, then reduce the heat, cover and simmer, stirring occasionally, for 30 mins.","Meanwhile, cook the spaghetti in a large pan of boiling, salted water, according to packet instructions. Drain well, run hot water through it, put it back in the pan and add a dash of olive oil, if you like, then stir in the meat sauce. Serve in hot bowls and hand round Parmesan cheese, for sprinkling on top."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52770","time":50,"cost":2,"tags":["mealprep","family","protein","healthy"]},{"id":"mdb-52844","title":"Lasagne","image":"https://www.themealdb.com/images/media/meals/wtsvxx1511296896.jpg","desc":"Italian · Pasta","category":"Pasta","serves":4,"diet":"meat","pork":true,"allergens":["gluten","dairy"],"base":"pasta","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"bacon","qty":2,"unit":"","cat":"meat","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"celery","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"beef","qty":500,"unit":"g","cat":"meat","text":""},{"name":"tomato purée","qty":1,"unit":"","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":800,"unit":"g","cat":"pantry","text":""},{"name":"honey","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"lasagne sheet","qty":500,"unit":"g","cat":"pantry","text":""},{"name":"creme fraiche","qty":400,"unit":"ml","cat":"dairy","text":""},{"name":"mozzarella","qty":125,"unit":"g","cat":"dairy","text":""},{"name":"parmesan","qty":50,"unit":"g","cat":"dairy","text":""},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"Topping"}],"steps":["Heat the oil in a large saucepan. Use kitchen scissors to snip the bacon into small pieces, or use a sharp knife to chop it on a chopping board. Add the bacon to the pan and cook for just a few mins until starting to turn golden. Add the onion, celery and carrot, and cook over a medium heat for 5 mins, stirring occasionally, until softened.","Add the garlic and cook for 1 min, then tip in the mince and cook, stirring and breaking it up with a wooden spoon, for about 6 mins until browned all over.","Stir in the tomato purée and cook for 1 min, mixing in well with the beef and vegetables. Tip in the chopped tomatoes. Fill each can half full with water to rinse out any tomatoes left in the can, and add to the pan. Add the honey and season to taste. Simmer for 20 mins.","Heat oven to 200C/180C fan/gas 6. To assemble the lasagne, ladle a little of the ragu sauce into the bottom of the roasting tin or casserole dish, spreading the sauce all over the base. Place 2 sheets of lasagne on top of the sauce overlapping to make it fit, then repeat with more sauce and another layer of pasta. Repeat with a further 2 layers of sauce and pasta, finishing with a layer of pasta.","Put the crème fraîche in a bowl and mix with 2 tbsp water to loosen it and make a smooth pourable sauce. Pour this over the top of the pasta, then top with the mozzarella. Sprinkle Parmesan over the top and bake for 25–30 mins until golden and bubbling. Serve scattered with basil, if you like."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/classic-lasagne","time":75,"cost":3,"tags":["mealprep","family","protein","healthy"]},{"id":"mdb-52982","title":"Spaghetti alla Carbonara","image":"https://www.themealdb.com/images/media/meals/llcbn01574260722.jpg","desc":"Italian · Pasta","category":"Pasta","serves":4,"diet":"meat","pork":true,"allergens":["gluten","dairy","egg"],"base":"pasta","ingredients":[{"name":"spaghetti","qty":320,"unit":"g","cat":"pantry","text":""},{"name":"egg yolk","qty":6,"unit":"","cat":"dairy","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"bacon","qty":150,"unit":"g","cat":"meat","text":""},{"name":"pecorino","qty":50,"unit":"g","cat":"dairy","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Put a large saucepan of water on to boil.","Finely chop the 100g pancetta, having first removed any rind. Finely grate 50g pecorino cheese and 50g parmesan and mix them together.","Beat the 3 large eggs in a medium bowl and season with a little freshly grated black pepper. Set everything aside.","Add 1 tsp salt to the boiling water, add 350g spaghetti and when the water comes back to the boil, cook at a constant simmer, covered, for 10 minutes or until al dente (just cooked).","Squash 2 peeled plump garlic cloves with the blade of a knife, just to bruise it.","While the spaghetti is cooking, fry the pancetta with the garlic. Drop 50g unsalted butter into a large frying pan or wok and, as soon as the butter has melted, tip in the pancetta and garlic.","Leave to cook on a medium heat for about 5 minutes, stirring often, until the pancetta is golden and crisp. The garlic has now imparted its flavour, so take it out with a slotted spoon and discard.","Keep the heat under the pancetta on low. When the pasta is ready, lift it from the water with a pasta fork or tongs and put it in the frying pan with the pancetta. Don’t worry if a little water drops in the pan as well (you want this to happen) and don’t throw the pasta water away yet.","Mix most of the cheese in with the eggs, keeping a small handful back for sprinkling over later.","Take the pan of spaghetti and pancetta off the heat. Now quickly pour in the eggs and cheese. Using the tongs or a long fork, lift up the spaghetti so it mixes easily with the egg mixture, which thickens but doesn’t scramble, and everything is coated.","Add extra pasta cooking water to keep it saucy (several tablespoons should do it). You don’t want it wet, just moist. Season with a little salt, if needed.","Use a long-pronged fork to twist the pasta on to the serving plate or bowl. Serve immediately with a little sprinkling of the remaining cheese and a grating of black pepper. If the dish does get a little dry before serving, splash in some more hot pasta water and the glossy sauciness will be revived."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/ultimate-spaghetti-carbonara-recipe","time":30,"cost":1,"tags":["money","quick","family","protein"]},{"id":"mdb-52771","title":"Spicy Arrabiata Penne","image":"https://www.themealdb.com/images/media/meals/ustsqw1468250014.jpg","desc":"Italian · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy"],"base":"pasta","ingredients":[{"name":"penne rigate","qty":454,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"cup","cat":"staple","text":""},{"name":"garlic","qty":3,"unit":"clove","cat":"veg","text":""},{"name":"chopped tomatoes","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"chilli flakes","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"italian seasoning","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"basil","qty":6,"unit":"","cat":"veg","text":""},{"name":"parmesan","qty":0,"unit":"","cat":"dairy","text":"sprinkling"}],"steps":["Bring a large pot of water to a boil. Add kosher salt to the boiling water, then add the pasta. Cook according to the package instructions, about 9 minutes.","In a large skillet over medium-high heat, add the olive oil and heat until the oil starts to shimmer. Add the garlic and cook, stirring, until fragrant, 1 to 2 minutes. Add the chopped tomatoes, red chile flakes, Italian seasoning and salt and pepper to taste. Bring to a boil and cook for 5 minutes. Remove from the heat and add the chopped basil.","Drain the pasta and add it to the sauce. Garnish with Parmigiano-Reggiano flakes and more basil and serve warm."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52771","time":30,"cost":1,"tags":["money","quick"]},{"id":"mdb-52839","title":"Chilli prawn linguine","image":"https://www.themealdb.com/images/media/meals/usywpp1511189717.jpg","desc":"Italian · Pasta","category":"Pasta","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","dairy","shellfish"],"base":"pasta","ingredients":[{"name":"linguine pasta","qty":280,"unit":"g","cat":"pantry","text":""},{"name":"sugar snap peas","qty":200,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"king prawn","qty":24,"unit":"","cat":"fish","text":""},{"name":"cherry tomato","qty":12,"unit":"","cat":"veg","text":""},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"Handful"},{"name":"lettuce","qty":0,"unit":"","cat":"veg","text":"Leaves"},{"name":"bread","qty":0,"unit":"","cat":"bakery","text":"to serve"},{"name":"fromage frai","qty":2,"unit":"tbsp","cat":"dairy","text":""},{"name":"lime","qty":0,"unit":"","cat":"veg","text":"Grated Zest of 2"},{"name":"sugar","qty":2,"unit":"tsp","cat":"pantry","text":""}],"steps":["Mix the dressing ingredients in a small bowl and season with salt and pepper. Set aside.","Cook the pasta according to the packet instructions. Add the sugar snap peas for the last minute or so of cooking time.","Meanwhile, heat the oil in a wok or large frying pan, toss in the garlic and chilli and cook over a fairly gentle heat for about 30 seconds without letting the garlic brown. Tip in the prawns and cook over a high heat, stirring frequently, for about 3 minutes until they turn pink.","Add the tomatoes and cook, stirring occasionally, for 3 minutes until they just start to soften. Drain the pasta and sugar snaps well, then toss into the prawn mixture. Tear in the basil leaves, stir, and season with salt and pepper.","Serve with salad leaves drizzled with the lime dressing, and warm crusty bread."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/1269/chilli-prawn-linguine","time":20,"cost":2,"tags":["quick","mealprep","protein","healthy"]},{"id":"mdb-52775","title":"Vegan Lasagna","image":"https://www.themealdb.com/images/media/meals/rvxxuy1468312893.jpg","desc":"Italian · Vegan","category":"Vegan","serves":4,"diet":"vegan","pork":false,"allergens":["gluten","dairy","soy"],"base":"pasta","ingredients":[{"name":"green red lentils","qty":1,"unit":"cup","cat":"pantry","text":""},{"name":"carrot","qty":1,"unit":"","cat":"veg","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"courgette","qty":1,"unit":"","cat":"veg","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"sprinking"},{"name":"spinach","qty":150,"unit":"g","cat":"veg","text":""},{"name":"lasagne sheet","qty":10,"unit":"","cat":"pantry","text":""},{"name":"vegan butter","qty":35,"unit":"g","cat":"dairy","text":""},{"name":"plain flour","qty":4,"unit":"tbsp","cat":"pantry","text":""},{"name":"soya milk","qty":300,"unit":"ml","cat":"pantry","text":""},{"name":"mustard","qty":1.5,"unit":"tsp","cat":"pantry","text":""},{"name":"vinegar","qty":1,"unit":"tsp","cat":"pantry","text":""}],"steps":["Preheat oven to 180 degrees celcius.","Boil vegetables for 5-7 minutes, until soft. Add lentils and bring to a gentle simmer, adding a stock cube if desired. Continue cooking and stirring until the lentils are soft, which should take about 20 minutes.","Blanch spinach leaves for a few minutes in a pan, before removing and setting aside.","Top up the pan with water and cook the lasagne sheets. When cooked, drain and set aside.","To make the sauce, melt the butter and add the flour, then gradually add the soya milk along with the mustard and the vinegar. Cook and stir until smooth and then assemble the lasagne as desired in a baking dish.","Bake in the preheated oven for about 25 minutes."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52775","time":65,"cost":1,"tags":["money","protein","healthy"]},{"id":"mdb-52777","title":"Mediterranean Pasta Salad","image":"https://www.themealdb.com/images/media/meals/wvqpwt1468339226.jpg","desc":"Italian · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","dairy","fish"],"base":"pasta","ingredients":[{"name":"mozzarella","qty":200,"unit":"g","cat":"dairy","text":""},{"name":"baby plum tomato","qty":250,"unit":"g","cat":"veg","text":""},{"name":"basil","qty":1,"unit":"","cat":"veg","text":""},{"name":"farfalle","qty":350,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"green olive","qty":40,"unit":"g","cat":"pantry","text":""},{"name":"tuna","qty":200,"unit":"g","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Bring a large saucepan of salted water to the boil","Add the pasta, stir once and cook for about 10 minutes or as directed on the packet.","Meanwhile, wash the tomatoes and cut into quarters. Slice the olives. Wash the basil.","Put the tomatoes into a salad bowl and tear the basil leaves over them. Add a tablespoon of olive oil and mix.","When the pasta is ready, drain into a colander and run cold water over it to cool it quickly.","Toss the pasta into the salad bowl with the tomatoes and basil.","Add the sliced olives, drained mozzarella balls, and chunks of tuna. Mix well and let the salad rest for at least half an hour to allow the flavours to mingle.","Sprinkle the pasta with a generous grind of black pepper and drizzle with the remaining olive oil just before serving."],"source":"TheMealDB","sourceUrl":"https://thelemonsqueezy.com/recipe/mediterranean-pasta-salad/","time":25,"cost":1,"tags":["money","quick","family"]},{"id":"mdb-52818","title":"Chicken Fajita Mac and Cheese","image":"https://www.themealdb.com/images/media/meals/qrqywr1503066605.jpg","desc":"United States · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy"],"base":"pasta","ingredients":[{"name":"macaroni","qty":500,"unit":"g","cat":"pantry","text":""},{"name":"chicken stock","qty":2,"unit":"cup","cat":"pantry","text":""},{"name":"cream","qty":0.5,"unit":"cup","cat":"dairy","text":""},{"name":"fajita seasoning","qty":1,"unit":"","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"chicken breast","qty":3,"unit":"","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":2,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"cheddar","qty":1,"unit":"cup","cat":"dairy","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":"garnish chopped"}],"steps":["Fry your onion, peppers and garlic in olive oil until nicely translucent. Make a well in your veg and add your chicken. Add your seasoning and salt. Allow to colour slightly.","Add your cream, stock and macaroni.","Cook on low for 20 minutes. Add your cheeses, stir to combine.","Top with roasted peppers and parsley."],"source":"TheMealDB","sourceUrl":"http://twistedfood.co.uk/chicken-fajita-mac-n-cheese/","time":35,"cost":2,"tags":["family","protein"]},{"id":"mdb-53367","title":"Chicken Fried Rice","image":"https://www.themealdb.com/images/media/meals/wuyd2h1765655837.jpg","desc":"Chinese · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","egg","soy","sesame"],"base":"rice","ingredients":[{"name":"chicken thigh","qty":454,"unit":"g","cat":"meat","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"canola oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"egg","qty":3,"unit":"","cat":"dairy","text":""},{"name":"onion","qty":0.6666666666666666,"unit":"cup","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"ground ginger","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"carrot","qty":1,"unit":"","cat":"veg","text":""},{"name":"frozen peas","qty":0.6666666666666666,"unit":"cup","cat":"frozen","text":""},{"name":"rice","qty":4,"unit":"cup","cat":"pantry","text":""},{"name":"spring onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"chinese five spice powder","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"soy sauce","qty":2.5,"unit":"tbsp","cat":"pantry","text":""},{"name":"sesame seed oil","qty":0,"unit":"tsp","cat":"staple","text":""}],"steps":["Fried rice is best made with leftover rice that's at least a day old. Otherwise it becomes gummy in the skillet.","If you don’t have any leftover rice from the night before, cook a batch of rice and spread it on a large baking sheet or several large plates. Let the rice dry out for about 1 to 2 hours before using it for fried rice.","Rice sticks to the pan very easily, so make sure to use a wok or pan that doesn’t have a sticky surface. I usually cook stir-fries in my seasoned carbon steel wok, but cast iron or nonstick pans work well, too. You might need to add a little more oil if things aren’t releasing easily.","Prepare the chicken:","Chop the chicken into small 1/4-inch to 1/2-inch cubes. Sprinkle 1/2 teaspoon of salt over the chicken and mix to combine. Set the chicken aside for about 10 minutes (I usually use this time to chop all the vegetables).","Scramble the egg:","Heat a wok or large sauté pan over medium-high heat. Swirl in a tablespoon of oil and add the whisked eggs. Use a spatula to quickly scramble the eggs, breaking the curds into smaller pieces as they come together. Transfer the eggs to a plate.","Cook the chicken:","Add another tablespoon of oil in the wok or pan. Add the chicken and cook for 4 to 5 minutes, stirring occasionally. Turn off the heat and transfer the cooked chicken to a plate.","Using your spatula, scrape off any chicken bits that are still stuck to the wok so they don't burn during the next step. You can also use paper towels to wipe down your wok or pan.","Cook the vegetables:","Swirl 1 tablespoon of oil into the wok over medium-high heat. Add the diced onions and cook them for 1 minute, until they start to soften. Mix in the minced garlic and ginger and cook until fragrant, about 30 seconds. Add the diced carrots and cook for 2 minutes, stirring frequently. Add 1/2 teaspoon salt and the peas, and stir to incorporate.","Cook the rice:","Add the rice to the wok or pan on top of the vegetables and stir to combine. Using the back of your spatula, smash any large chunks of rice to break them apart. Add the white and green parts of the sliced scallions (save the dark green parts) and five-spice powder. Stir to incorporate. If the rice starts to stick to the pan, stir in a little more oil.","Drizzle the soy sauce and sesame oil over the rice and stir to incorporate. Stir in the cooked chicken, scrambled eggs, and the dark parts of the scallions. Stir briefly to bring it together, and cook for another 1 to 2 minutes.","Serve:","Taste, and add more soy sauce if necessary. Serve immediately."],"source":"TheMealDB","sourceUrl":"https://www.simplyrecipes.com/recipes/chicken_fried_rice/","time":35,"cost":2,"tags":["protein","healthy"]},{"id":"mdb-52814","title":"Thai Green Curry","image":"https://www.themealdb.com/images/media/meals/sstssx1487349585.jpg","desc":"Thai · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["fish"],"base":"rice","ingredients":[{"name":"potato","qty":225,"unit":"g","cat":"veg","text":""},{"name":"green beans","qty":100,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""},{"name":"thai green curry paste","qty":4,"unit":"tsp","cat":"pantry","text":""},{"name":"coconut milk","qty":400,"unit":"ml","cat":"pantry","text":""},{"name":"thai fish sauce","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"sugar","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"chicken","qty":450,"unit":"g","cat":"meat","text":""},{"name":"lime","qty":2,"unit":"","cat":"veg","text":""},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"handfull"},{"name":"rice","qty":0,"unit":"","cat":"pantry","text":"Boiled"}],"steps":["Put the potatoes in a pan of boiling water and cook for 5 minutes. Throw in the beans and cook for a further 3 minutes, by which time both should be just tender but not too soft. Drain and put to one side.","In a wok or large frying pan, heat the oil until very hot, then drop in the garlic and cook until golden, this should take only a few seconds. Don’t let it go very dark or it will spoil the taste. Spoon in the curry paste and stir it around for a few seconds to begin to cook the spices and release all the flavours. Next, pour in the coconut milk and let it come to a bubble.","Stir in the fish sauce and sugar, then the pieces of chicken. Turn the heat down to a simmer and cook, covered, for about 8 minutes until the chicken is cooked.","Tip in the potatoes and beans and let them warm through in the hot coconut milk, then add a lovely citrussy flavour by stirring in the shredded lime leaves (or lime zest). The basil leaves go in next, but only leave them briefly on the heat or they will quickly lose their brightness. Scatter with the lime garnish and serve immediately with boiled rice."],"source":"TheMealDB","sourceUrl":"http://www.bbcgoodfood.com/recipes/3235/thai-green-chicken-curry","time":30,"cost":2,"tags":["quick","mealprep","protein","healthy"]},{"id":"mdb-52772","title":"Teriyaki Chicken Casserole","image":"https://www.themealdb.com/images/media/meals/wvpsxx1468256321.jpg","desc":"Japanese · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","soy"],"base":"rice","ingredients":[{"name":"soy sauce","qty":0.75,"unit":"cup","cat":"pantry","text":""},{"name":"brown sugar","qty":0.25,"unit":"cup","cat":"pantry","text":""},{"name":"ground ginger","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"garlic","qty":0.5,"unit":"tsp","cat":"veg","text":""},{"name":"cornstarch","qty":4,"unit":"tbsp","cat":"pantry","text":""},{"name":"chicken breast","qty":2,"unit":"","cat":"meat","text":""},{"name":"stir-fry vegetable","qty":1,"unit":"","cat":"veg","text":""},{"name":"rice","qty":3,"unit":"cup","cat":"pantry","text":""}],"steps":["Preheat oven to 350° F. Spray a 9x13-inch baking pan with non-stick spray.","Combine soy sauce, ½ cup water, brown sugar, ginger and garlic in a small saucepan and cover. Bring to a boil over medium heat. Remove lid and cook for one minute once boiling.","Meanwhile, stir together the corn starch and 2 tablespoons of water in a separate dish until smooth. Once sauce is boiling, add mixture to the saucepan and stir to combine. Cook until the sauce starts to thicken then remove from heat.","Place the chicken breasts in the prepared pan. Pour one cup of the sauce over top of chicken. Place chicken in oven and bake 35 minutes or until cooked through. Remove from oven and shred chicken in the dish using two forks.","*Meanwhile, steam or cook the vegetables according to package directions.","Add the cooked vegetables and rice to the casserole dish with the chicken. Add most of the remaining sauce, reserving a bit to drizzle over the top when serving. Gently toss everything together in the casserole dish until combined. Return to oven and cook 15 minutes. Remove from oven and let stand 5 minutes before serving. Drizzle each serving with remaining sauce. Enjoy!"],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52772","time":70,"cost":1,"tags":["money","mealprep","protein"]},{"id":"mdb-53184","title":"Spanish rice & prawn one-pot","image":"https://www.themealdb.com/images/media/meals/sl6vqv1763335988.jpg","desc":"Spanish · Seafood","category":"Seafood","serves":4,"diet":"meat","pork":true,"allergens":["shellfish"],"base":"rice","ingredients":[{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":1,"unit":"","cat":"veg","text":""},{"name":"green pepper","qty":1,"unit":"","cat":"veg","text":""},{"name":"chorizo","qty":50,"unit":"g","cat":"meat","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"rice","qty":250,"unit":"g","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":400,"unit":"g","cat":"pantry","text":""},{"name":"prawn","qty":200,"unit":"g","cat":"fish","text":""}],"steps":["Boil the kettle. In a non-stick frying or shallow pan with a lid, fry the onion, peppers, chorizo and garlic in the oil over a high heat for 3 mins. Stir in the rice and chopped tomatoes with 500ml boiling water, cover, then cook over a high heat for 12 mins.","Uncover, then stir – the rice should be almost tender. Stir in the prawns, with a splash more water if the rice is looking dry, then cook for another min until the prawns are just pink and rice tender."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/spanish-rice-prawn-one-pot","time":30,"cost":2,"tags":["quick","protein","healthy"]},{"id":"mdb-53506","title":"Rice and Beans","image":"https://www.themealdb.com/images/media/meals/j8c1d51782772399.jpg","desc":"Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"rice","ingredients":[{"name":"kidney beans","qty":0.5,"unit":"","cat":"pantry","text":""},{"name":"coconut milk","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"scotch bonnet","qty":3,"unit":"","cat":"veg","text":""},{"name":"salt & pepper","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"tbsp","cat":"staple","text":""}],"steps":["Cook beans until tender, add rice, coconut milk, onion, black pepper and salt, and add enough water to just cover the ingredients. Place Scotch Bonnet peppers on top, careful not to burst them. Simmer until rice is tender. Remove pepper before serving."],"source":"TheMealDB","sourceUrl":"https://www.ourcayman.ky/en-us/about/more-about-cayman/recipes","time":15,"cost":1,"tags":["money","quick","protein"]},{"id":"mdb-52868","title":"Kidney Bean Curry","image":"https://www.themealdb.com/images/media/meals/sywrsu1511463066.jpg","desc":"India · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"rice","ingredients":[{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"ginger","qty":1,"unit":"","cat":"veg","text":""},{"name":"coriander","qty":1,"unit":"","cat":"veg","text":""},{"name":"cumin","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"paprika","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"garam masala","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":400,"unit":"g","cat":"pantry","text":""},{"name":"kidney beans","qty":400,"unit":"g","cat":"pantry","text":""},{"name":"rice","qty":0,"unit":"","cat":"pantry","text":"to serve"}],"steps":["Heat the oil in a large frying pan over a low-medium heat. Add the onion and a pinch of salt and cook slowly, stirring occasionally, until softened and just starting to colour. Add the garlic, ginger and coriander stalks and cook for a further 2 mins, until fragrant.","Add the spices to the pan and cook for another 1 min, by which point everything should smell aromatic. Tip in the chopped tomatoes and kidney beans in their water, then bring to the boil.","Turn down the heat and simmer for 15 mins until the curry is nice and thick. Season to taste, then serve with the basmati rice and the coriander leaves."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/kidney-bean-curry","time":35,"cost":1,"tags":["money","mealprep","protein","healthy"]},{"id":"mdb-53198","title":"Thai fried rice with prawns & peas","image":"https://www.themealdb.com/images/media/meals/hblwvg1763478203.jpg","desc":"Thai · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","egg","fish","shellfish","soy"],"base":"rice","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"red onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"","cat":"veg","text":""},{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"king prawn","qty":250,"unit":"g","cat":"fish","text":""},{"name":"rice","qty":140,"unit":"g","cat":"pantry","text":""},{"name":"frozen peas","qty":75,"unit":"g","cat":"frozen","text":""},{"name":"soy sauce","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"fish sauce","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Bunch"},{"name":"egg","qty":4,"unit":"","cat":"dairy","text":""},{"name":"hotsauce","qty":0,"unit":"","cat":"pantry","text":"To serve"}],"steps":["Heat 1 tbsp of the oil in a wok, add the onion, garlic and chilli, and cook for 2-3 mins until golden. Add the prawns and cook for 1 min. Tip in the rice and peas, and keep tossing until very hot. Add the soy and fish sauce, then stir through the chopped coriander. Keep warm while you fry the eggs.","Heat the remaining oil in a frying pan and fry the eggs with some seasoning. Divide the fried rice mix between 4 bowls and top each with a fried egg. Serve scattered with coriander, with chilli sauce, if you like."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/thai-fried-rice-prawns-peas","time":15,"cost":2,"tags":["quick","protein","healthy"]},{"id":"mdb-52820","title":"Katsu Chicken curry","image":"https://www.themealdb.com/images/media/meals/vwrpps1503068729.jpg","desc":"Japanese · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","egg","soy"],"base":"none","ingredients":[{"name":"chicken breast","qty":4,"unit":"","cat":"meat","text":""},{"name":"plain flour","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"egg","qty":1,"unit":"","cat":"dairy","text":""},{"name":"breadcrumbs","qty":100,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"ml","cat":"staple","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":5,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":2,"unit":"","cat":"veg","text":""},{"name":"plain flour","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"curry powder","qty":4,"unit":"tsp","cat":"pantry","text":""},{"name":"chicken stock","qty":600,"unit":"ml","cat":"pantry","text":""},{"name":"honey","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"soy sauce","qty":4,"unit":"tsp","cat":"pantry","text":""},{"name":"bay leaf","qty":1,"unit":"","cat":"pantry","text":""},{"name":"garam masala","qty":1,"unit":"tsp","cat":"pantry","text":""}],"steps":["Prep:15min  ›  Cook:30min  ›  Ready in:45min","For the curry sauce: Heat oil in medium non-stick saucepan, add onion and garlic and cook until softened. Stir in carrots and cook over low heat for 10 to 12 minutes.","Add flour and curry powder; cook for 1 minute. Gradually stir in stock until combined; add honey, soy sauce and bay leaf. Slowly bring to the boil.","Turn down heat and simmer for 20 minutes or until sauce thickens but is still of pouring consistency. Stir in garam masala. Pour the curry sauce through a sieve; return to saucepan and keep on low heat until ready to serve.","For the chicken: Season both sides of chicken breasts with salt and pepper. Place flour, egg and breadcrumbs in separate bowls and arrange in a row. Coat the chicken breasts in flour, then dip them into the egg, then coat in breadcrumbs, making sure you cover both sides.","Heat oil in large frying pan over medium-high heat. Place chicken into hot oil and cook until golden brown, about 3 or 4 minutes each side. Once cooked, place on kitchen paper to absorb excess oil.","Pour curry sauce over chicken, serve with white rice and enjoy!"],"source":"TheMealDB","sourceUrl":"http://allrecipes.co.uk/recipe/29578/chicken-katsu-curry.aspx","time":45,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52774","title":"Pad See Ew","image":"https://www.themealdb.com/images/media/meals/uuuspp1468263334.jpg","desc":"Thai · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","egg","peanuts","shellfish","soy"],"base":"noodles","ingredients":[{"name":"rice stick noodles","qty":168,"unit":"g","cat":"pantry","text":""},{"name":"soy sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"oyster sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"soy sauce","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"white vinegar","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"sugar","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"peanut oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"chicken","qty":1,"unit":"cup","cat":"meat","text":""},{"name":"egg","qty":1,"unit":"","cat":"dairy","text":""},{"name":"chinese broccoli","qty":4,"unit":"cup","cat":"veg","text":""}],"steps":["Mix Sauce in small bowl.","Mince garlic into wok with oil. Place over high heat, when hot, add chicken and Chinese broccoli stems, cook until chicken is light golden.","Push to the side of the wok, crack egg in and scramble. Don't worry if it sticks to the bottom of the wok - it will char and which adds authentic flavour.","Add noodles, Chinese broccoli leaves and sauce. Gently mix together until the noodles are stained dark and leaves are wilted. Serve immediately!"],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52774","time":15,"cost":2,"tags":["quick","protein"]},{"id":"mdb-53191","title":"Pad Thai","image":"https://www.themealdb.com/images/media/meals/rg9ze01763479093.jpg","desc":"Thai · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","peanuts","fish","shellfish"],"base":"noodles","ingredients":[{"name":"rice noodles","qty":125,"unit":"g","cat":"pantry","text":""},{"name":"lime","qty":0,"unit":"","cat":"veg","text":"Juice of 3"},{"name":"cayenne pepper","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"muscovado sugar","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"fish sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"tiger prawn","qty":200,"unit":"g","cat":"fish","text":""},{"name":"spring onion","qty":4,"unit":"","cat":"veg","text":""},{"name":"bean sprouts","qty":140,"unit":"g","cat":"veg","text":""},{"name":"peanut","qty":25,"unit":"g","cat":"veg","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Handful"},{"name":"lime","qty":2,"unit":"","cat":"veg","text":""},{"name":"sweet chilli sauce","qty":0,"unit":"","cat":"pantry","text":"To serve"}],"steps":["Put the noodles in a large heatproof bowl, pour boiling water over them and leave for 4 minutes, then drain and refresh under cold running water.","Put the lime juice, cayenne, sugar and fish sauce in a bowl and mix well. Have all the other ingredients ready by the cooker.","Heat the oil and fry the prawns until warmed through. Add the spring onions and noodles and toss around. Tip in the lime juice mixture, then stir in the beansprouts and half the peanuts and coriander. Cook for 1 minute until everything is heated through.","Pile into a large dish, scatter with the rest of the peanuts and coriander, and serve with lime wedges and sweet chilli sauce."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/easy-pad-thai","time":20,"cost":2,"tags":["quick","protein","healthy"]},{"id":"mdb-53368","title":"Singapore Noodles with Shrimp","image":"https://www.themealdb.com/images/media/meals/f3cxnc1765656994.jpg","desc":"Chinese · Seafood","category":"Seafood","serves":4,"diet":"meat","pork":true,"allergens":["gluten","egg","shellfish","soy","sesame"],"base":"noodles","ingredients":[{"name":"sesame seed oil","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"soy sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"seasoned rice vinegar","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"vermicelli rice noodles","qty":168,"unit":"g","cat":"pantry","text":""},{"name":"egg","qty":2,"unit":"","cat":"dairy","text":""},{"name":"ground ginger","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""},{"name":"carrot","qty":2,"unit":"","cat":"veg","text":""},{"name":"jalapeno","qty":1,"unit":"","cat":"veg","text":""},{"name":"onion","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"ham","qty":112,"unit":"g","cat":"meat","text":""},{"name":"napa cabbage","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"spring onion","qty":4,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"curry powder","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"shrimp","qty":227,"unit":"g","cat":"fish","text":""},{"name":"cilantro leaves","qty":2,"unit":"tbsp","cat":"veg","text":""}],"steps":["For the sweet onion, look for Vidalia, OSO Sweet, or Walla Walla. The super-sweet varieties are more suited to this stir-fry because at the end of cooking, the onion still has a slight crunch.","Make the sauce:","In a bowl, combine the sesame oil, soy sauce, and rice vinegar.","Cook the rice noodles:","Bring a large saucepan of water to a boil, add the noodles, and use tongs to turn them so they are submerged. Cook for 2 minutes, or until they are tender but still have some bite (they will cook a little more once you add them to the skillet).","Drain, rinse with cold water, and use scissors to snip the noodles several times to break them up into shorter lengths.","Scramble the eggs:","In a small bowl whisk together the eggs. Heat the skillet or Dutch oven over medium heat. Add 1 tablespoon of the peanut or canola oil. Add the eggs and scramble them for 2 minutes, or until they form large, soft curds. Transfer them from the pan to a plate or bowl.","Cook the vegetables:","Add 1 tablespoon of the remaining oil to the pan. When it is hot, add the ginger, garlic, carrots, jalapeño, onion, and salt. Cook, stirring constantly, for 2 minutes or until the vegetables start to soften.","Add the remaining ingredients:","Sprinkle the vegetable mixture with the remaining 1 tablespoon peanut or canola oil. When the oil is hot, add the ham, cabbage, scallions, red pepper, and curry powder to the pan. Cook, stirring constantly, for 1 minute.","Add the shrimp and cook, stirring, for 3 more minutes or until the shrimp are bright pink and cooked through.","Add the noodles in batches:","Add the eggs, the sauce mixture, and half the noodles to the pan. Toss for 1 minute.","Add the remaining noodles and continue tossing for 1 minute more until they are thoroughly combined and the mixture is heated through.","Serve:","Taste for seasoning and add more salt or soy sauce, if you like. Sprinkle with cilantro leaves and serve."],"source":"TheMealDB","sourceUrl":"https://www.simplyrecipes.com/recipes/singapore_noodles_with_shrimp/","time":25,"cost":3,"tags":["quick","protein","healthy"]},{"id":"mdb-53195","title":"Thai curry noodle soup","image":"https://www.themealdb.com/images/media/meals/118oj61763423896.jpg","desc":"Thai · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","shellfish"],"base":"noodles","ingredients":[{"name":"oil","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"thai green curry paste","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"stir-fry vegetable","qty":220,"unit":"g","cat":"veg","text":""},{"name":"king prawn","qty":150,"unit":"g","cat":"fish","text":""},{"name":"coconut milk","qty":150,"unit":"ml","cat":"pantry","text":""},{"name":"vegetable stock","qty":225,"unit":"ml","cat":"pantry","text":""},{"name":"udon noodles","qty":250,"unit":"g","cat":"pantry","text":""},{"name":"coriander","qty":10,"unit":"g","cat":"veg","text":""},{"name":"basil","qty":10,"unit":"g","cat":"veg","text":""},{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"spring onion","qty":1,"unit":"","cat":"veg","text":""}],"steps":["Heat the oil in a saucepan over a medium heat and cook the curry paste for 1 min before adding the stir-fry veg and prawns. Cook for 3 mins until the prawns are mostly pink, then add the coconut milk, veg stock and noodles.","Bring to the boil, then reduce the heat to a simmer and cook for 5 mins until the noodles are cooked through and the veg is tender but still has a bite. Divide between two bowls and sprinkle over the herbs, chilli and spring onion."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/thai-curry-noodle-soup","time":25,"cost":2,"tags":["quick","mealprep","protein","healthy"]},{"id":"mdb-52781","title":"Irish stew","image":"https://www.themealdb.com/images/media/meals/sxxpst1468569714.jpg","desc":"Irish · Beef","category":"Beef","serves":4,"diet":"meat","pork":false,"allergens":["gluten"],"base":"potato","ingredients":[{"name":"whole wheat","qty":300,"unit":"g","cat":"veg","text":""},{"name":"lamb loin chop","qty":2000,"unit":"g","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"ml","cat":"staple","text":""},{"name":"shallot","qty":24,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":4,"unit":"","cat":"veg","text":""},{"name":"turnip","qty":2,"unit":"","cat":"veg","text":""},{"name":"celeriac","qty":1,"unit":"","cat":"veg","text":""},{"name":"charlotte potato","qty":350,"unit":"g","cat":"veg","text":""},{"name":"white wine","qty":150,"unit":"ml","cat":"pantry","text":""},{"name":"sugar","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"thyme","qty":4,"unit":"","cat":"veg","text":""},{"name":"oregano","qty":4,"unit":"","cat":"pantry","text":""},{"name":"chicken stock","qty":450,"unit":"ml","cat":"pantry","text":""}],"steps":["Heat the oven to 180C/350F/gas mark 4. Drain and rinse the soaked wheat, put it in a medium pan with lots of water, bring to a boil and simmer for an hour, until cooked. Drain and set aside.","Season the lamb with a teaspoon of salt and some black pepper. Put one tablespoon of oil in a large, deep sauté pan for which you have a lid; place on a medium-high heat. Add some of the lamb – don't overcrowd the pan – and sear for four minutes on all sides. Transfer to a bowl, and repeat with the remaining lamb, adding oil as needed.","Lower the heat to medium and add a tablespoon of oil to the pan. Add the shallots and fry for four minutes, until caramelised. Tip these into the lamb bowl, and repeat with the remaining vegetables until they are all nice and brown, adding more oil as you need it.","Once all the vegetables are seared and removed from the pan, add the wine along with the sugar, herbs, a teaspoon of salt and a good grind of black pepper. Boil on a high heat for about three minutes.","Tip the lamb, vegetables and whole wheat back into the pot, and add the stock. Cover and boil for five minutes, then transfer to the oven for an hour and a half.","Remove the stew from the oven and check the liquid; if there is a lot, remove the lid and boil for a few minutes."],"source":"TheMealDB","sourceUrl":"http://www.ottolenghi.co.uk/recipes/meat/irish-stew-shop","time":60,"cost":3,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52884","title":"Lancashire hotpot","image":"https://www.themealdb.com/images/media/meals/uttrxw1511637813.jpg","desc":"British · Lamb","category":"Lamb","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy","fish"],"base":"potato","ingredients":[{"name":"butter","qty":100,"unit":"g","cat":"dairy","text":""},{"name":"lamb","qty":900,"unit":"g","cat":"meat","text":""},{"name":"lamb kidney","qty":3,"unit":"","cat":"meat","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":4,"unit":"","cat":"veg","text":""},{"name":"plain flour","qty":25,"unit":"g","cat":"pantry","text":""},{"name":"worcestershire sauce","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"chicken stock","qty":500,"unit":"ml","cat":"pantry","text":""},{"name":"bay leaf","qty":2,"unit":"","cat":"pantry","text":""},{"name":"potato","qty":900,"unit":"g","cat":"veg","text":""}],"steps":["Heat oven to 160C/fan 140C/gas 3. Heat some dripping or butter in a large shallow casserole dish, brown the lamb in batches, lift to a plate, then repeat with the kidneys.","Fry the onions and carrots in the pan with a little more dripping until golden. Sprinkle over the flour, allow to cook for a couple of mins, shake over the Worcestershire sauce, pour in the stock, then bring to the boil. Stir in the meat and bay leaves, then turn off the heat. Arrange the sliced potatoes on top of the meat, then drizzle with a little more dripping. Cover, then place in the oven for about 1½ hrs until the potatoes are cooked.","Remove the lid, brush the potatoes with a little more dripping, then turn the oven up to brown the potatoes, or finish under the grill for 5-8 mins until brown."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/9099/lancashire-hotpot","time":60,"cost":3,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52846","title":"Chicken & mushroom Hotpot","image":"https://www.themealdb.com/images/media/meals/uuuspp1511297945.jpg","desc":"British · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy"],"base":"potato","ingredients":[{"name":"butter","qty":50,"unit":"g","cat":"dairy","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"mushroom","qty":100,"unit":"g","cat":"veg","text":""},{"name":"plain flour","qty":40,"unit":"g","cat":"pantry","text":""},{"name":"chicken stock","qty":1,"unit":"","cat":"pantry","text":""},{"name":"nutmeg","qty":0,"unit":"","cat":"pantry","text":"pinch"},{"name":"mustard powder","qty":0,"unit":"","cat":"pantry","text":"pinch"},{"name":"chicken","qty":250,"unit":"g","cat":"meat","text":""},{"name":"sweetcorn","qty":2,"unit":"","cat":"pantry","text":""},{"name":"potato","qty":2,"unit":"","cat":"veg","text":""},{"name":"butter","qty":1,"unit":"","cat":"dairy","text":""}],"steps":["Heat oven to 200C/180C fan/gas 6. Put the butter in a medium-size saucepan and place over a medium heat. Add the onion and leave to cook for 5 mins, stirring occasionally. Add the mushrooms to the saucepan with the onions.","Once the onion and mushrooms are almost cooked, stir in the flour – this will make a thick paste called a roux. If you are using a stock cube, crumble the cube into the roux now and stir well. Put the roux over a low heat and stir continuously for 2 mins – this will cook the flour and stop the sauce from having a floury taste.","Take the roux off the heat. Slowly add the fresh stock, if using, or pour in 500ml water if you’ve used a stock cube, stirring all the time. Once all the liquid has been added, season with pepper, a pinch of nutmeg and mustard powder. Put the saucepan back onto a medium heat and slowly bring it to the boil, stirring all the time. Once the sauce has thickened, place on a very low heat. Add the cooked chicken and vegetables to the sauce and stir well. Grease a medium-size ovenproof pie dish with a little butter and pour in the chicken and mushroom filling.","Carefully lay the potatoes on top of the hot-pot filling, overlapping them slightly, almost like a pie top.","Brush the potatoes with a little melted butter and cook in the oven for about 35 mins. The hot-pot is ready once the potatoes are cooked and golden brown."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/chicken-mushroom-hot-pot","time":60,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-53000","title":"Vegetable Shepherds Pie","image":"https://www.themealdb.com/images/media/meals/w8umt11583268117.jpg","desc":"Irish · Beef","category":"Beef","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy","soy"],"base":"potato","ingredients":[{"name":"potato","qty":1362,"unit":"g","cat":"veg","text":""},{"name":"potato","qty":1362,"unit":"g","cat":"veg","text":""},{"name":"butter","qty":0.5,"unit":"cup","cat":"dairy","text":""},{"name":"mushroom","qty":28,"unit":"g","cat":"veg","text":""},{"name":"brown lentils","qty":0.75,"unit":"cup","cat":"pantry","text":""},{"name":"garlic","qty":6,"unit":"clove","cat":"veg","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"onion","qty":3,"unit":"cup","cat":"veg","text":""},{"name":"tomato purée","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"bay leaf","qty":0,"unit":"","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"dry white wine","qty":2,"unit":"cup","cat":"pantry","text":""},{"name":"vegetable stock","qty":8,"unit":"cup","cat":"pantry","text":""},{"name":"cornstarch","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"soy sauce","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"rosemary","qty":2,"unit":"","cat":"veg","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":""},{"name":"sage","qty":0,"unit":"","cat":"veg","text":""},{"name":"chive","qty":0,"unit":"","cat":"veg","text":""}],"steps":["Add Ingredients:","12 cups chopped mixed vegetables","1   cup chopped fresh mushrooms","1   cup pearl onions","TOPPING:","Preheat oven to 450°. Bake potatoes on a foil-lined baking sheet until tender, about 45 minutes. Let cool slightly, then peel. Press potatoes through a ricer, food mill, or colander into a large bowl. Add butter; stir until well blended. Stir in milk. Season to taste with salt.","FILLING:","Soak dried porcini in 3 cups hot water; set aside. Combine lentils, 1 garlic clove, 1 tsp. salt, and 4 cups water in a medium saucepan. Bring to a boil; reduce heat and simmer, stirring occasionally, until lentils are tender but not mushy, 15–20 minutes. Drain lentils and discard garlic.","Heat 3 Tbsp. oil in a large heavy pot over medium heat. Add onions and cook, stirring occasionally, until soft, about 12 minutes. Add chopped garlic and cook for 1 minute. Stir in tomato paste. Cook, stirring constantly, until tomato paste is caramelized, 2–3 minutes.","Add bay leaves and wine; stir, scraping up any browned bits. Stir in porcini, slowly pouring porcini soaking liquid into pan but leaving any sediment behind. Bring to a simmer and cook until liquid is reduced by half, about 10 minutes. Stir in broth and cook, stirring occasionally, until reduced by half, about 45 minutes.","Strain mixture into a large saucepan and bring to a boil; discard solids in strainer. Stir cornstarch and 2 Tbsp. water in a small bowl to dissolve. Add cornstarch mixture; simmer until thickened, about 5 minutes. Whisk in miso. Season sauce with salt and pepper. Set aside.","Preheat oven to 450°. Toss vegetables and pearl onions with remaining 2 Tbsp. oil, 5 garlic cloves, and rosemary sprigs in a large bowl; season with salt and pepper. Divide between 2 rimmed baking sheets. Roast, stirring once, until tender, 20–25 minutes. Transfer garlic cloves to a small bowl; mash well with a fork and stir into sauce. Discard rosemary. DO AHEAD: Lentils, sauce, and vegetables can be made 1 day ahead. Cover separately; chill.","Arrange lentils in an even layer in a 3-qt. baking dish; set dish on a foil-lined rimmed baking sheet. Toss roasted vegetables with fresh mushrooms and chopped herbs; layer on top of lentils. Pour sauce over vegetables. Spoon potato mixture evenly over.","Bake until browned and bubbly, about 30 minutes. Let stand for 15 minutes before serving."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/53000","time":180,"cost":2,"tags":["mealprep","family","protein","healthy"]},{"id":"mdb-52802","title":"Fish pie","image":"https://www.themealdb.com/images/media/meals/ysxwuq1487323065.jpg","desc":"British · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","dairy","fish","shellfish"],"base":"potato","ingredients":[{"name":"potato","qty":900,"unit":"g","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"milk","qty":600,"unit":"ml","cat":"dairy","text":""},{"name":"white fish fillet","qty":800,"unit":"g","cat":"fish","text":""},{"name":"plain flour","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"nutmeg","qty":0,"unit":"","cat":"pantry","text":"Grating"},{"name":"cream","qty":3,"unit":"tbsp","cat":"dairy","text":""},{"name":"jerusalem artichoke","qty":200,"unit":"g","cat":"veg","text":""},{"name":"leek","qty":1,"unit":"","cat":"veg","text":""},{"name":"prawn","qty":200,"unit":"g","cat":"fish","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":"Large handful"},{"name":"dill","qty":0,"unit":"","cat":"veg","text":"Handful"},{"name":"lemon","qty":0,"unit":"","cat":"veg","text":"Grated zest of 1"},{"name":"gruyère","qty":25,"unit":"g","cat":"dairy","text":""},{"name":"lemon","qty":0,"unit":"","cat":"veg","text":"Juice of 1"}],"steps":["Put the potatoes in a large pan of cold salted water and bring to the boil. Lower the heat, cover, then simmer gently for 15 minutes until tender. Drain, then return to the pan over a low heat for 30 seconds to drive off any excess water. Mash with 1 tbsp olive oil, then season.","Meanwhile put the milk in a large sauté pan, add the fish and bring to the boil. Remove from the heat, cover and stand for 3 minutes. Remove the fish (reserving the milk) and pat dry with kitchen paper, then gently flake into an ovenproof dish, discarding the skin and any bones.","Heat the remaining oil in a pan, stir in the flour and cook for 30 seconds. Gradually stir in 200-250ml of the reserved milk (discard the rest). Grate in nutmeg, season, then bubble until thick. Stir in the cream.","Preheat the oven to 190°C/fan170°C/gas 5. Grate the artichokes and add to the dish with the leek, prawns and herbs. Stir the lemon zest and juice into the sauce, then pour over. Mix gently with a wooden spoon.","Spoon the mash onto the fish mixture, then use a fork to make peaks, which will crisp and brown as it cooks. Sprinkle over the cheese, then bake for 35-40 minutes until golden and bubbling. Serve with wilted greens."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52802","time":70,"cost":3,"tags":["mealprep","family","protein"]},{"id":"mdb-52993","title":"Honey Balsamic Chicken with Crispy Broccoli & Potatoes","image":"https://www.themealdb.com/images/media/meals/kvbotn1581012881.jpg","desc":"United States · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["dairy"],"base":"potato","ingredients":[{"name":"potato","qty":5,"unit":"","cat":"veg","text":""},{"name":"broccoli","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"chicken breast","qty":2,"unit":"","cat":"meat","text":""},{"name":"balsamic vinegar","qty":0,"unit":"","cat":"pantry","text":""},{"name":"honey","qty":0,"unit":"","cat":"pantry","text":""},{"name":"chicken stock","qty":0,"unit":"","cat":"pantry","text":""},{"name":"butter","qty":1,"unit":"tbsp","cat":"dairy","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""}],"steps":["2 Servings","Preheat oven to 425 degrees. Wash and dry all produce. Cut potatoes into 1/2-inch-thick wedges. Toss on one side of a baking sheet with a drizzle of oil, salt, and pepper. (For 4 servings, spread potatoes out across entire sheet.) Roast on top rack for 5 minutes (we'll add the broccoli then).","Meanwhile, cut broccoli florets into bite-size pieces, if necessary. Peel and finely chop garlic. In a small microwave-safe bowl, combine 1 TBSP olive oil (2 TBSP for 4 servings) and half the garlic. Microwave until garlic sizzles, 30 seconds.","Once potatoes have roasted 5 minutes, remove sheet from oven and add broccoli to empty side; carefully toss with garlic oil, salt, and pepper. (For 4 servings, add broccoli to a second sheet.) Continue roasting until potatoes and broccoli are browned and crispy, 15-20 minutes more.","While veggies roast, pat chicken dry with paper towels; season all over with salt and pepper. Heat a drizzle of oil in a large pan over medium-high heat. Add chicken and cook until browned and cooked through, 5-6 minutes per side. (If chicken browns too quickly, reduce heat to medium.) Turn off heat; set chicken aside to rest. Wash out pan.","Heat pan used for chicken over medium-high heat. Add a drizzle of oil and remaining garlic; cook until fragrant, 30 seconds. Stir in vinegar, honey, stock concentrate, and 1/4 cup water (1/3 cup for 4 servings). Simmer until thick and glossy, 2-3 minutes. Remove from heat and stir in 1 TBSP butter (2 TBSP for 4). Season with salt and pepper.","Return chicken to pan and turn to coat in glaze. Divide chicken, broccoli, and potatoes between plates. Spoon any remaining glaze over chicken and serve."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52993","time":50,"cost":1,"tags":["money","protein","healthy"]},{"id":"mdb-52996","title":"French Onion Chicken with Roasted Carrots & Mashed Potatoes","image":"https://www.themealdb.com/images/media/meals/b5ft861583188991.jpg","desc":"United States · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["dairy"],"base":"potato","ingredients":[{"name":"chicken breast","qty":2,"unit":"","cat":"meat","text":""},{"name":"carrot","qty":336,"unit":"g","cat":"veg","text":""},{"name":"potato","qty":5,"unit":"","cat":"veg","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"beef stock","qty":1,"unit":"","cat":"pantry","text":""},{"name":"mozzarella","qty":1.5,"unit":"cup","cat":"dairy","text":""},{"name":"sour cream","qty":2,"unit":"tbsp","cat":"dairy","text":""},{"name":"butter","qty":0,"unit":"","cat":"dairy","text":""},{"name":"sugar","qty":0,"unit":"","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Preheat oven to 425 degrees. Wash and dry all produce. Trim, peel, and cut carrots on a diagonal into ¼-inch-thick pieces. Dice potatoes into ½-inch pieces. Halve, peel, and thinly slice onion.","Toss carrots on a baking sheet with a drizzle of oil, salt, and pepper. Roast until browned and tender, 15-20 minutes.","Meanwhile, place potatoes in a medium pot with enough salted water to cover by 2 inches. Bring to a boil and cook until tender, 12-15 minutes. Drain and return potatoes to pot; cover to keep warm.","While potatoes cook, heat a drizzle of oil in a large pan over medium-high heat. Add onion and cook, stirring occasionally, until lightly browned and softened, 8-10 minutes. Sprinkle with 1 tsp sugar (2 tsp for 4 servings). Stir in stock concentrate and 2 TBSP water (¼ cup for 4); season with salt and pepper. Cook until jammy, 2-3 minutes more. Turn off heat; transfer to a small bowl. Wash out pan.","Pat chicken dry with paper towels; season all over with salt and pepper. Heat a drizzle of oil in pan used for onion over medium-high heat. Add chicken and cook until browned and cooked through, 5-6 minutes per side. In the last 1-2 minutes of cooking, top with caramelized onion and cheese. Cover pan until cheese melts. (If your pan doesn’t have a lid, cover with a baking sheet!)","Heat pot with drained potatoes over low heat; mash with sour cream, 2 TBSP butter (4 TBSP for 4 servings), salt, pepper, and a splash of water (or milk, for extra richness) until smooth. Divide chicken, roasted carrots, and mashed potatoes between plates."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52996","time":65,"cost":2,"tags":["protein"]},{"id":"mdb-52780","title":"Potato Gratin with Chicken","image":"https://www.themealdb.com/images/media/meals/qwrtut1468418027.jpg","desc":"Italian · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":true,"allergens":["dairy"],"base":"potato","ingredients":[{"name":"potato","qty":800,"unit":"g","cat":"veg","text":""},{"name":"onion","qty":3,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"chicken stock","qty":100,"unit":"ml","cat":"pantry","text":""},{"name":"creme fraiche","qty":1,"unit":"","cat":"dairy","text":""},{"name":"parmesan","qty":0,"unit":"","cat":"dairy","text":"Topping"},{"name":"chicken breast","qty":4,"unit":"","cat":"meat","text":""},{"name":"bacon","qty":4,"unit":"","cat":"meat","text":""},{"name":"spinach","qty":0,"unit":"","cat":"veg","text":"Topping"},{"name":"frozen peas","qty":0,"unit":"","cat":"frozen","text":"Topping"}],"steps":["15 minute potato gratin with chicken and bacon greens: a gratin always seems more effort and more indulgent than ordinary boiled or roasts, but it doesn't have to take 45mins, it's nice for a change and you can control the calorie content by going with full fat to low fat creme fraiche. (It's always tastes better full fat though obviously!) to serve 4: use 800g of potatoes, finely slice and boil in a pan for about 5-8 mins till firmish, not soft. Finely slice 3 onions and place in an oven dish with 2 tblsp of olive oil and 100ml of chicken stock. Cook till the onions are soft then drain the potatoes and pour onto the onions. Season and spoon over cream or creme fraiche till all is covered but not swimming. Grate Parmesan over the top then finish under the grill till nicely golden. serve with chicken and bacon, peas and spinach."],"source":"TheMealDB","sourceUrl":"https://www.instagram.com/p/BHxR7hYBJ6P","time":80,"cost":2,"tags":["protein"]},{"id":"mdb-53159","title":"Chorizo, potato & cheese omelette","image":"https://www.themealdb.com/images/media/meals/0y6uvc1763258983.jpg","desc":"Spanish · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":["dairy","egg"],"base":"potato","ingredients":[{"name":"potato","qty":1,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"chorizo","qty":50,"unit":"g","cat":"meat","text":""},{"name":"egg","qty":3,"unit":"","cat":"dairy","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":"Chopped"},{"name":"cheddar","qty":25,"unit":"g","cat":"dairy","text":""}],"steps":["Cook the potato in boiling water for 8-10 mins or until tender. Drain and allow to steam-dry. Heat oil in an omelette pan, add chorizo and cook for 2 mins. Add the potato and cook for a further 5 mins until the potato starts to crisp. Spoon pan contents out, wipe pan and cook a 2 or 3-egg omelette in the same pan. When almost cooked, scatter with the chorizo and potato, parsley and cheese. Fold the omelette in the pan and cook for 1 min more to melt the cheese."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/chorizo-potato-cheese-omelette","time":30,"cost":1,"tags":["money","quick","protein"]},{"id":"mdb-52872","title":"Spanish Tortilla","image":"https://www.themealdb.com/images/media/meals/quuxsx1511476154.jpg","desc":"Spanish · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy","egg"],"base":"potato","ingredients":[{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"butter","qty":25,"unit":"g","cat":"dairy","text":""},{"name":"potato","qty":400,"unit":"g","cat":"veg","text":""},{"name":"garlic","qty":6,"unit":"clove","cat":"veg","text":""},{"name":"egg","qty":8,"unit":"","cat":"dairy","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":"Handful"},{"name":"baguette","qty":1,"unit":"","cat":"bakery","text":""},{"name":"vine tomato","qty":4,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Put a large non-stick frying pan on a low heat. Cook the onion slowly in the oil and butter until soft but not brown – this should take about 15 mins. Add the potatoes, cover the pan and cook for a further 15-20 mins, stirring occasionally to make sure they fry evenly.","When the potatoes are soft and the onion is shiny, crush 2 garlic cloves and stir in, followed by the beaten eggs.","Put the lid back on the pan and leave the tortilla to cook gently. After 20 mins, the edges and base should be golden, the top set but the middle still a little wobbly. To turn it over, slide it onto a plate and put another plate on top, turn the whole thing over and slide it back into the pan to finish cooking. Once cooked, transfer to a plate and serve the tortilla warm or cold, scattered with the chopped parsley.","To accompany, take slices of warmed baguette, stab all over with a fork and rub with the remaining garlic, pile on grated tomatoes and season with sea salt and a drizzle of olive oil."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/spanish-tortilla","time":70,"cost":1,"tags":["money","protein","healthy"]},{"id":"mdb-53098","title":"Cumberland Pie","image":"https://www.themealdb.com/images/media/meals/pvfkz61761595976.jpg","desc":"British · Beef","category":"Beef","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy","fish"],"base":"potato","ingredients":[{"name":"celery","qty":2,"unit":"","cat":"veg","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":2,"unit":"","cat":"veg","text":""},{"name":"bay leaf","qty":5,"unit":"","cat":"pantry","text":""},{"name":"thyme","qty":3,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"butter","qty":1,"unit":"tbsp","cat":"dairy","text":""},{"name":"plain flour","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"tomato purée","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"worcestershire sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"beef stock","qty":2,"unit":"","cat":"pantry","text":""},{"name":"feather blade beef","qty":800,"unit":"g","cat":"meat","text":""},{"name":"potato","qty":800,"unit":"g","cat":"veg","text":""},{"name":"cheddar","qty":25,"unit":"g","cat":"dairy","text":""},{"name":"parmesan","qty":25,"unit":"g","cat":"dairy","text":""}],"steps":["Heat oven to 160C/140C fan/gas 3. Soften the celery, onion, carrots, bay and 1 thyme sprig in a casserole with 1 tbsp oil and the butter for 10 mins. Stir in the flour, followed by the purée, Worcestershire sauce and stock cubes.","Gradually stir in 600ml hot water, then tip in the beef and bring to a gentle simmer. Cover and cook in the oven for 2 hrs 30 mins, then uncover and cook for 30 mins -1 hr more until the meat is really tender and sauce thickened.","Meanwhile, cook potatoes in a pan of boiling water until they’re not done but about ¾ of the way there.","Transfer meat to a baking dish. Slice spuds into 1cm thick rounds and gently toss with seasoning, the remaining oil and thyme leaves. Layer on the beef, scattering with the cheese as you layer. You can cover and chill the pie now for 1 day, or freeze for up to 3 months.","Increase oven to 200C/180C fan/gas 6 and bake for 30-40 mins until golden and crispy, and sauce bubbling if the dish went in cold. Serve with peas."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/crispy-topped-cumberland-pie","time":180,"cost":3,"tags":["mealprep","family","protein"]},{"id":"mdb-52885","title":"Bubble & Squeak","image":"https://www.themealdb.com/images/media/meals/xusqvw1511638311.jpg","desc":"British · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":["dairy"],"base":"potato","ingredients":[{"name":"butter","qty":1,"unit":"tbsp","cat":"dairy","text":""},{"name":"bacon","qty":4,"unit":"","cat":"meat","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":1,"unit":"","cat":"veg","text":""},{"name":"brussels sprouts","qty":20,"unit":"","cat":"veg","text":""},{"name":"potato","qty":400,"unit":"g","cat":"veg","text":""}],"steps":["Melt the fat in a non-stick pan, allow it to get nice and hot, then add the bacon. As it begins to brown, add the onion and garlic. Next, add the sliced sprouts or cabbage and let it colour slightly. All this will take 5-6 mins.","Next, add the potato. Work everything together in the pan and push it down so that the mixture covers the base of the pan – allow the mixture to catch slightly on the base of the pan before turning it over and doing the same again. It’s the bits of potato that catch in the pan that define the term ‘bubble and squeak’, so be brave and let the mixture colour. Cut into wedges and serve."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/164622/bubble-and-squeak","time":20,"cost":1,"tags":["money","quick","protein"]},{"id":"mdb-53036","title":"Boxty Breakfast","image":"https://www.themealdb.com/images/media/meals/naqyel1608588563.jpg","desc":"Irish · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":["gluten","dairy","egg"],"base":"potato","ingredients":[{"name":"potato","qty":4,"unit":"","cat":"veg","text":""},{"name":"spring onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"plain flour","qty":100,"unit":"g","cat":"pantry","text":""},{"name":"egg white","qty":1,"unit":"","cat":"dairy","text":""},{"name":"milk","qty":150,"unit":"ml","cat":"dairy","text":""},{"name":"bicarbonate of soda","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"butter","qty":3,"unit":"tbsp","cat":"dairy","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"cherry tomato","qty":6,"unit":"","cat":"veg","text":""},{"name":"bacon","qty":12,"unit":"","cat":"meat","text":""},{"name":"egg","qty":6,"unit":"","cat":"dairy","text":""}],"steps":["Before you start, put your oven on its lowest setting, ready to keep things warm. Peel the potatoes, grate 2 of them, then set aside. Cut the other 2 into large chunks, then boil for 10-15 mins or until tender. Meanwhile, squeeze as much of the liquid from the grated potatoes as you can using a clean tea towel. Mash the boiled potatoes, then mix with the grated potato, spring onions and flour.","Whisk the egg white in a large bowl until it holds soft peaks. Fold in the buttermilk, then add the bicarbonate of soda. Fold into the potato mix.","Heat a large non-stick frying pan over a medium heat, then add 1 tbsp butter and some of the oil. Drop 3-4 spoonfuls of the potato mixture into the pan, then gently cook for 3-5 mins on each side until golden and crusty. Keep warm on a plate in the oven while you cook the next batch, adding more butter and oil to the pan before you do so. You will get 16 crumpet-size boxty from the mix. Can be made the day ahead, drained on kitchen paper, then reheated in a low oven for 20 mins.","Heat the grill to medium and put the tomatoes in a heavy-based pan. Add a good knob of butter and a little oil, then fry for about 5 mins until softened. Grill the bacon, then pile onto a plate and keep warm. Stack up the boxty, bacon and egg, and serve the tomatoes on the side."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/boxty-bacon-eggs-tomatoes","time":55,"cost":2,"tags":["protein"]},{"id":"mdb-53453","title":"Bengali Chicken Curry with Potatoes","image":"https://www.themealdb.com/images/media/meals/9ya6o71780262651.jpg","desc":"Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":[],"base":"potato","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"ginger garlic paste","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"tomato","qty":2,"unit":"","cat":"veg","text":""},{"name":"cayenne pepper","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"curry powder","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"garam masala","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"ground turmeric","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"cumin","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"chicken breast","qty":4,"unit":"","cat":"meat","text":""},{"name":"red potato","qty":2,"unit":"","cat":"veg","text":""},{"name":"coriander","qty":0.5,"unit":"cup","cat":"veg","text":""}],"steps":["Heat the olive oil in a large skillet over medium-high heat. Cook and stir the onions in the hot oil until translucent, about 5 minutes. Add the ginger-garlic paste and continue cooking another 5 minutes. Reduce heat to medium; stir the tomatoes into the mixture and cook until the tomatoes are pulpy, 5 to 10 minutes. Season with the cayenne pepper, curry powder, garam masala, turmeric, and cumin; cook and stir another 5 minutes.","Add the chicken and potatoes to the mixture in the skillet; simmer, stirring occasionally, until the potatoes are tender and the chicken is no longer pink in the center, about 20 minutes. Sprinkle the cilantro over the mixture and continue simmering another 10 minutes. Serve hot."],"source":"TheMealDB","sourceUrl":"https://www.allrecipes.com/recipe/215055/bengali-chicken-curry-with-potatoes/","time":70,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-53085","title":"15-minute chicken & halloumi burgers","image":"https://www.themealdb.com/images/media/meals/vdwloy1713225718.jpg","desc":"United States · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy","egg"],"base":"bread","ingredients":[{"name":"chicken breast","qty":2,"unit":"","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"hotsauce","qty":4,"unit":"tbsp","cat":"pantry","text":""},{"name":"lemon","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"bun","qty":2,"unit":"","cat":"bakery","text":""},{"name":"cheese","qty":250,"unit":"g","cat":"dairy","text":""},{"name":"cabbage","qty":0.25,"unit":"","cat":"veg","text":""},{"name":"mayonnaise","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"sour cream","qty":4,"unit":"tbsp","cat":"dairy","text":""},{"name":"lettuce","qty":4,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":2,"unit":"","cat":"veg","text":""}],"steps":["Put the chicken breasts between two pieces of baking parchment and use a rolling pin to gently bash them until they are approximately 1cm thick. Cut each chicken breast into two even pieces.","If you're using a frying pan, heat two frying pans over medium-high heat, with one of them containing oil. Fry the chicken in the oiled pan for 3-4 mins on each side until they are cooked through. Season the chicken, reduce the heat, drizzle in the chilli sauce and half of the lemon juice, and cook for an additional 1-2 mins until the sauce is reduced. Remove the chicken from the heat.","If you're using an air-fryer, preheat it to 180C for 4 mins. Add the chicken to the air-fryer and cook for 12 mins. Drizzle over the chilli sauce and half the lemon juice and cook for an additional 1-2 mins until the chicken is cooked through and the sauce is reduced. Remove the chicken and keep it warm.","While the chicken is cooking, toast the buns in the dry frying pan for 30 seconds. Transfer them to a plate. If you're using an air fryer, put the buns in the air fryer for 1-2 mins until they are warm. Increase the air fryer temperature to 200C. Add the halloumi to the air fryer basket and cook for 10 mins, turning halfway through, until it's golden. Toss the cabbage with the mayo and the remaining lemon juice.","Spoon the hummus (or dip of your choice) into the toasted buns, then top with the rocket, chilli chicken, halloumi, and peppers. Drizzle with a little more chilli sauce, spoon over the cabbage, season with black pepper, and top with the bun lids. Serve with any extra cabbage on the side or a green salad."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/15-minute-chicken-halloumi-burgers","time":50,"cost":2,"tags":["family","protein"]},{"id":"mdb-52870","title":"Chickpea Fajitas","image":"https://www.themealdb.com/images/media/meals/tvtxpq1511464705.jpg","desc":"Mexican · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy"],"base":"bread","ingredients":[{"name":"chickpeas","qty":400,"unit":"g","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"paprika","qty":0,"unit":"","cat":"pantry","text":"pinch"},{"name":"tomato","qty":2,"unit":"","cat":"veg","text":""},{"name":"red onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"red wine vinegar","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"avocado","qty":1,"unit":"","cat":"veg","text":""},{"name":"lime","qty":0,"unit":"","cat":"veg","text":"Juice of 1"},{"name":"lime","qty":0,"unit":"","cat":"veg","text":"Chopped"},{"name":"sour cream","qty":100,"unit":"g","cat":"dairy","text":""},{"name":"harissa spice","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"corn tortilla","qty":4,"unit":"","cat":"bakery","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"to serve"}],"steps":["Heat oven to 200C/180C fan/gas 6 and line a baking tray with foil. Drain the chickpeas, pat dry and tip onto the prepared baking tray. Add the oil and paprika, toss to coat, then roast for 20-25 mins until browned and crisp, shaking halfway through cooking.","Meanwhile, put the tomatoes and onion in a small bowl with the vinegar and set aside to pickle. Put the avocado in another bowl and mash with a fork, leaving some larger chunks. Stir in the lime juice and season well. Mix the soured cream with the harissa and set aside until ready to serve.","Heat a griddle pan until nearly smoking. Add the tortillas , one at a time, charring each side until hot with griddle lines.","Put everything on the table and build the fajitas : spread a little of the harissa cream over the tortilla, top with roasted chickpeas, guacamole, pickled salsa and coriander, if you like. Serve with the lime wedges for squeezing over."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/chickpea-fajitas","time":40,"cost":2,"tags":["family","protein","healthy"]},{"id":"mdb-52819","title":"Cajun spiced fish tacos","image":"https://www.themealdb.com/images/media/meals/uvuyxu1503067369.jpg","desc":"Mexican · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","dairy","fish"],"base":"bread","ingredients":[{"name":"cajun","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"cayenne pepper","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"white fish","qty":4,"unit":"","cat":"fish","text":""},{"name":"oil","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"tortilla wraps","qty":8,"unit":"","cat":"bakery","text":""},{"name":"avocado","qty":1,"unit":"","cat":"veg","text":""},{"name":"little gem lettuce","qty":2,"unit":"","cat":"veg","text":""},{"name":"spring onion","qty":4,"unit":"","cat":"veg","text":""},{"name":"salsa","qty":1,"unit":"","cat":"pantry","text":""},{"name":"sour cream","qty":1,"unit":"","cat":"dairy","text":""},{"name":"lemon","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""}],"steps":["Cooking in a cajun spice and cayenne pepper marinade makes this fish super succulent and flavoursome. Top with a zesty dressing and serve in a tortilla for a quick, fuss-free main that's delightfully summery.","On a large plate, mix the cajun spice and cayenne pepper with a little seasoning and use to coat the fish all over.","Heat a little oil in a frying pan, add in the fish and cook over a medium heat until golden. Reduce the heat and continue frying until the fish is cooked through, about 10 minutes. Cook in batches if you don’t have enough room in the pan.","Meanwhile, prepare the dressing by combining all the ingredients with a little seasoning.","Soften the tortillas by heating in the microwave for 5-10 seconds. Pile high with the avocado, lettuce and spring onion, add a spoonful of salsa, top with large flakes of fish and drizzle over the dressing."],"source":"TheMealDB","sourceUrl":"https://realfood.tesco.com/recipes/cajun-spiced-fish-tacos.html","time":25,"cost":2,"tags":["quick","family","protein","healthy"]},{"id":"mdb-53014","title":"Pizza Express Margherita","image":"https://www.themealdb.com/images/media/meals/x0lk931587671540.jpg","desc":"Italian · Miscellaneous","category":"Miscellaneous","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy"],"base":"bread","ingredients":[{"name":"sugar","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"yeast","qty":15,"unit":"g","cat":"pantry","text":""},{"name":"plain flour","qty":225,"unit":"g","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"passata","qty":80,"unit":"g","cat":"pantry","text":""},{"name":"mozzarella","qty":70,"unit":"g","cat":"dairy","text":""},{"name":"oregano","qty":0,"unit":"","cat":"pantry","text":"Peeled and Sliced"},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"Leaves"},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["1 Preheat the oven to 230°C.","2 Add the sugar and crumble the fresh yeast into warm water.","3 Allow the mixture to stand for 10 – 15 minutes in a warm place (we find a windowsill on a sunny day works best) until froth develops on the surface.","4 Sift the flour and salt into a large mixing bowl, make a well in the middle and pour in the yeast mixture and olive oil.","5 Lightly flour your hands, and slowly mix the ingredients together until they bind.","6 Generously dust your surface with flour.","7 Throw down the dough and begin kneading for 10 minutes until smooth, silky and soft.","8 Place in a lightly oiled, non-stick baking tray (we use a round one, but any shape will do!)","9 Spread the passata on top making sure you go to the edge.","10 Evenly place the mozzarella (or other cheese) on top, season with the oregano and black pepper, then drizzle with a little olive oil.","11 Cook in the oven for 10 – 12 minutes until the cheese slightly colours.","12 When ready, place the basil leaf on top and tuck in!"],"source":"TheMealDB","sourceUrl":"https://www.dailymail.co.uk/femail/food/article-8240361/Pizza-Express-release-secret-recipe-Margherita-Pizza-make-home.html","time":50,"cost":1,"tags":["money","family"]},{"id":"mdb-52765","title":"Chicken Enchilada Casserole","image":"https://www.themealdb.com/images/media/meals/qtuwxu1468233098.jpg","desc":"Mexican · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy"],"base":"bread","ingredients":[{"name":"enchilada sauce","qty":392,"unit":"g","cat":"pantry","text":""},{"name":"shredded monterey jack cheese","qty":3,"unit":"cup","cat":"dairy","text":""},{"name":"corn tortilla","qty":6,"unit":"","cat":"bakery","text":""},{"name":"chicken breast","qty":2,"unit":"","cat":"meat","text":""}],"steps":["Cut each chicken breast in about 3 pieces, so that it cooks faster and put it in a small pot. Pour Enchilada sauce over it and cook covered on low to medium heat until chicken is cooked through, about 20 minutes. No water is needed, the chicken will cook in the Enchilada sauce. Make sure you stir occasionally so that it doesn't stick to the bottom.","Remove chicken from the pot and shred with two forks.","Preheat oven to 375 F degrees.","Start layering the casserole. Start with about ¼ cup of the leftover Enchilada sauce over the bottom of a baking dish. I used a longer baking dish, so that I can put 2 corn tortillas across. Place 2 tortillas on the bottom, top with ⅓ of the chicken and ⅓ of the remaining sauce. Sprinkle with ⅓ of the cheese and repeat starting with 2 more tortillas, then chicken, sauce, cheese. Repeat with last layer with the remaining ingredients, tortillas, chicken, sauce and cheese.","Bake for 20 to 30 minutes uncovered, until bubbly and cheese has melted and started to brown on top.","Serve warm."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52765","time":60,"cost":1,"tags":["money","mealprep","protein"]},{"id":"mdb-52874","title":"Beef and Mustard Pie","image":"https://www.themealdb.com/images/media/meals/sytuqu1511553755.jpg","desc":"British · Beef","category":"Beef","serves":4,"diet":"meat","pork":false,"allergens":["gluten","dairy","egg"],"base":"bread","ingredients":[{"name":"beef","qty":1000,"unit":"g","cat":"meat","text":""},{"name":"plain flour","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"red wine","qty":200,"unit":"ml","cat":"pantry","text":""},{"name":"beef stock","qty":400,"unit":"ml","cat":"pantry","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":2,"unit":"","cat":"veg","text":""},{"name":"thyme","qty":3,"unit":"","cat":"veg","text":""},{"name":"mustard","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"egg yolk","qty":2,"unit":"","cat":"dairy","text":""},{"name":"puff pastry","qty":400,"unit":"g","cat":"bakery","text":""},{"name":"green beans","qty":300,"unit":"g","cat":"pantry","text":""},{"name":"butter","qty":25,"unit":"g","cat":"dairy","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Preheat the oven to 150C/300F/Gas 2.","Toss the beef and flour together in a bowl with some salt and black pepper.","Heat a large casserole until hot, add half of the rapeseed oil and enough of the beef to just cover the bottom of the casserole.","Fry until browned on each side, then remove and set aside. Repeat with the remaining oil and beef.","Return the beef to the pan, add the wine and cook until the volume of liquid has reduced by half, then add the stock, onion, carrots, thyme and mustard, and season well with salt and pepper.","Cover with a lid and place in the oven for two hours.","Remove from the oven, check the seasoning and set aside to cool. Remove the thyme.","When the beef is cool and you're ready to assemble the pie, preheat the oven to 200C/400F/Gas 6.","Transfer the beef to a pie dish, brush the rim with the beaten egg yolks and lay the pastry over the top. Brush the top of the pastry with more beaten egg.","Trim the pastry so there is just enough excess to crimp the edges, then place in the oven and bake for 30 minutes, or until the pastry is golden-brown and cooked through.","For the green beans, bring a saucepan of salted water to the boil, add the beans and cook for 4-5 minutes, or until just tender.","Drain and toss with the butter, then season with black pepper.","To serve, place a large spoonful of pie onto each plate with some green beans alongside."],"source":"TheMealDB","sourceUrl":"https://www.bbc.co.uk/food/recipes/beef_and_mustard_pie_58002","time":60,"cost":3,"tags":["mealprep","family","protein"]},{"id":"mdb-53011","title":"Chicken Quinoa Greek Salad","image":"https://www.themealdb.com/images/media/meals/k29viq1585565980.jpg","desc":"Greek · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["dairy"],"base":"grains","ingredients":[{"name":"quinoa","qty":225,"unit":"g","cat":"pantry","text":""},{"name":"butter","qty":25,"unit":"g","cat":"dairy","text":""},{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""},{"name":"chicken breast","qty":400,"unit":"g","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"black olive","qty":0,"unit":"","cat":"pantry","text":"Handful"},{"name":"red onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"feta","qty":100,"unit":"g","cat":"dairy","text":""},{"name":"mint","qty":0,"unit":"","cat":"veg","text":"Chopped"},{"name":"lemon","qty":0,"unit":"","cat":"veg","text":"Juice of 1/2"}],"steps":["Cook the quinoa following the pack instructions, then rinse in cold water and drain thoroughly.","Meanwhile, mix the butter, chilli and garlic into a paste. Toss the chicken fillets in 2 tsp of the olive oil with some seasoning. Lay in a hot griddle pan and cook for 3-4 mins each side or until cooked through. Transfer to a plate, dot with the spicy butter and set aside to melt.","Next, tip the tomatoes, olives, onion, feta and mint into a bowl. Toss in the cooked quinoa. Stir through the remaining olive oil, lemon juice and zest, and season well. Serve with the chicken fillets on top, drizzled with any buttery chicken juices."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/griddled-chicken-quinoa-greek-salad","time":20,"cost":2,"tags":["quick","protein","healthy"]},{"id":"mdb-53067","title":"Stuffed Bell Peppers with Quinoa and Black Beans","image":"https://www.themealdb.com/images/media/meals/b66myb1683207208.jpg","desc":"Mexican · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["dairy"],"base":"grains","ingredients":[{"name":"green pepper","qty":4,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"quinoa","qty":1,"unit":"cup","cat":"pantry","text":""},{"name":"black beans","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"sweetcorn","qty":1,"unit":"cup","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"cumin","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"chilli powder","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"paprika","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"shredded mexican cheese","qty":1.5,"unit":"cup","cat":"dairy","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Chopped"}],"steps":["Preheat your oven to 375°F (190°C). Lightly grease a 9x13-inch baking dish or a similar-sized casserole dish.","Place the bell pepper halves in the prepared baking dish, cut side up. Bake for 15-20 minutes, or until slightly softened.","While the bell peppers are baking, prepare the filling. In a large skillet, heat the olive oil over medium heat. Add the chopped onion, and cook for 3-4 minutes, until softened. Add the garlic, and cook for another 1 minute, until fragrant.","Stir in the cooked quinoa, black beans, corn, diced tomatoes, ground cumin, chili powder, smoked paprika, salt, and pepper. Cook for 5-7 minutes, until heated through. Remove the skillet from heat, and stir in 1 cup of the shredded cheese, if using.","Remove the bell peppers from the oven, and carefully stuff each pepper half with the quinoa and black bean mixture. Top the stuffed peppers with the remaining 1/2 cup of shredded cheese, if using.","Return the stuffed peppers to the oven, and bake for another 15-20 minutes, until the cheese is melted and the peppers are tender.","Remove from the oven, and allow the stuffed peppers to cool for 5 minutes before serving. Garnish with fresh chopped cilantro."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/53067","time":60,"cost":1,"tags":["money","protein","healthy"]},{"id":"mdb-53267","title":"Aubergine couscous salad","image":"https://www.themealdb.com/images/media/meals/02s6gc1763799560.jpg","desc":"Turkish · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["gluten","dairy"],"base":"grains","ingredients":[{"name":"aubergine","qty":1,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"couscous","qty":140,"unit":"g","cat":"pantry","text":""},{"name":"vegetable stock","qty":225,"unit":"g","cat":"pantry","text":""},{"name":"cherry tomato","qty":200,"unit":"g","cat":"veg","text":""},{"name":"mint","qty":0,"unit":"","cat":"veg","text":"Handful"},{"name":"goats cheese","qty":100,"unit":"g","cat":"dairy","text":""},{"name":"lemon","qty":0,"unit":"","cat":"veg","text":"Juice of 1/2"}],"steps":["Heat grill to high. Put the aubergine on a baking sheet, brush with oil and season. Grill for about 15 mins, turning and brushing with more oil halfway, until browned and softened.","Meanwhile, tip the couscous into a large bowl, pour over the stock, then cover and leave for 10 mins. Mix the tomatoes, mint, goat’s cheese and remaining oil together. Fluff the couscous up with a fork, then stir in the aubergines, tomato mixture and lemon juice."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/aubergine-couscous-salad","time":40,"cost":1,"tags":["money","healthy"]},{"id":"mdb-52963","title":"Shakshuka","image":"https://www.themealdb.com/images/media/meals/g373701551450225.jpg","desc":"Egyptian · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegetarian","pork":false,"allergens":["dairy","egg"],"base":"none","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"red onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":1,"unit":"clove","cat":"veg","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Chopped"},{"name":"cherry tomato","qty":800,"unit":"g","cat":"veg","text":""},{"name":"sugar","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"egg","qty":4,"unit":"","cat":"dairy","text":""},{"name":"feta","qty":0,"unit":"","cat":"dairy","text":"Spinkling"}],"steps":["Heat the oil in a frying pan that has a lid, then soften the onions, chilli, garlic and coriander stalks for 5 mins until soft. Stir in the tomatoes and sugar, then bubble for 8-10 mins until thick. Can be frozen for 1 month.","Using the back of a large spoon, make 4 dips in the sauce, then crack an egg into each one. Put a lid on the pan, then cook over a low heat for 6-8 mins, until the eggs are done to your liking. Scatter with the coriander leaves and serve with crusty bread."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/7573/spicy-tomato-baked-eggs","time":30,"cost":1,"tags":["money","quick","protein","healthy"]},{"id":"mdb-52867","title":"Vegetarian Chilli","image":"https://www.themealdb.com/images/media/meals/wqurxy1511453156.jpg","desc":"British · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"roasted vegetable","qty":400,"unit":"g","cat":"veg","text":""},{"name":"kidney beans","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":1,"unit":"tin","cat":"pantry","text":""},{"name":"mixed grain","qty":1,"unit":"","cat":"pantry","text":""}],"steps":["Heat oven to 200C/180C fan/ gas 6. Cook the vegetables in a casserole dish for 15 mins. Tip in the beans and tomatoes, season, and cook for another 10-15 mins until piping hot. Heat the pouch in the microwave on High for 1 min and serve with the chilli."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/veggie-chilli","time":45,"cost":1,"tags":["money","mealprep","protein"]},{"id":"mdb-52848","title":"Bean & Sausage Hotpot","image":"https://www.themealdb.com/images/media/meals/vxuyrx1511302687.jpg","desc":"British · Miscellaneous","category":"Miscellaneous","serves":4,"diet":"meat","pork":true,"allergens":[],"base":"none","ingredients":[{"name":"sausage","qty":8,"unit":"","cat":"meat","text":""},{"name":"tomato sauce","qty":1,"unit":"","cat":"pantry","text":""},{"name":"butter beans","qty":1200,"unit":"g","cat":"pantry","text":""},{"name":"black treacle","qty":1,"unit":"","cat":"pantry","text":""},{"name":"english mustard","qty":1,"unit":"tsp","cat":"pantry","text":""}],"steps":["In a large casserole, fry the sausages until brown all over – about 10 mins.","Add the tomato sauce, stirring well, then stir in the beans, treacle or sugar and mustard. Bring to the simmer, cover and cook for 30 mins. Great served with crusty bread or rice."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/339607/bean-and-sausage-hotpot","time":60,"cost":1,"tags":["money","mealprep","family","protein"]},{"id":"mdb-52863","title":"Vegetarian Casserole","image":"https://www.themealdb.com/images/media/meals/vptwyt1511450962.jpg","desc":"British · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":3,"unit":"clove","cat":"veg","text":""},{"name":"paprika","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"cumin","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"thyme","qty":1,"unit":"tbsp","cat":"veg","text":""},{"name":"carrot","qty":3,"unit":"","cat":"veg","text":""},{"name":"celery","qty":2,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":1,"unit":"","cat":"veg","text":""},{"name":"yellow pepper","qty":1,"unit":"","cat":"veg","text":""},{"name":"tomato","qty":2,"unit":"","cat":"veg","text":""},{"name":"vegetable stock","qty":250,"unit":"ml","cat":"pantry","text":""},{"name":"courgette","qty":2,"unit":"","cat":"veg","text":""},{"name":"thyme","qty":2,"unit":"","cat":"veg","text":""},{"name":"lentils","qty":250,"unit":"g","cat":"pantry","text":""}],"steps":["Heat the oil in a large, heavy-based pan. Add the onions and cook gently for 5 – 10 mins until softened.","Add the garlic, spices, dried thyme, carrots, celery and peppers and cook for 5 minutes.","Add the tomatoes, stock, courgettes and fresh thyme and cook for 20 - 25 minutes.","Take out the thyme sprigs. Stir in the lentils and bring back to a simmer. Serve with wild and white basmati rice, mash or quinoa."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/1993645/vegetarian-casserole","time":60,"cost":1,"tags":["money","mealprep","protein","healthy"]},{"id":"mdb-52841","title":"Creamy Tomato Soup","image":"https://www.themealdb.com/images/media/meals/stpuws1511191310.jpg","desc":"British · Starter","category":"Starter","serves":4,"diet":"vegetarian","pork":false,"allergens":["dairy"],"base":"potato","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"celery","qty":2,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":300,"unit":"g","cat":"veg","text":""},{"name":"potato","qty":500,"unit":"g","cat":"veg","text":""},{"name":"bay leaf","qty":4,"unit":"","cat":"pantry","text":""},{"name":"tomato purée","qty":5,"unit":"tbsp","cat":"pantry","text":""},{"name":"sugar","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"white vinegar","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"chopped tomatoes","qty":1500,"unit":"g","cat":"pantry","text":""},{"name":"passata","qty":500,"unit":"g","cat":"pantry","text":""},{"name":"vegetable stock","qty":3,"unit":"","cat":"pantry","text":""},{"name":"milk","qty":400,"unit":"ml","cat":"dairy","text":""}],"steps":["Put the oil, onions, celery, carrots, potatoes and bay leaves in a big casserole dish, or two saucepans. Fry gently until the onions are softened – about 10-15 mins. Fill the kettle and boil it.","Stir in the tomato purée, sugar, vinegar, chopped tomatoes and passata, then crumble in the stock cubes. Add 1 litre boiling water and bring to a simmer. Cover and simmer for 15 mins until the potato is tender, then remove the bay leaves. Purée with a stick blender (or ladle into a blender in batches) until very smooth. Season to taste and add a pinch more sugar if it needs it. The soup can now be cooled and chilled for up to 2 days, or frozen for up to 3 months.","To serve, reheat the soup, stirring in the milk – try not to let it boil. Serve in small bowls with cheesy sausage rolls."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/2604646/creamy-tomato-soup","time":45,"cost":1,"tags":["money","mealprep","healthy"]},{"id":"mdb-53486","title":"Easy White Bean Soup","image":"https://www.themealdb.com/images/media/meals/p5nzbk1782680889.jpg","desc":"Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"cannellini beans","qty":454,"unit":"g","cat":"pantry","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"red pepper","qty":2,"unit":"","cat":"veg","text":""},{"name":"tomato purée","qty":0.3333333333333333,"unit":"cup","cat":"pantry","text":""},{"name":"carrot","qty":2,"unit":"","cat":"veg","text":""},{"name":"dried mint","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"thyme","qty":0.5,"unit":"tsp","cat":"veg","text":""},{"name":"summer savoury","qty":1,"unit":"tsp","cat":"veg","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"parsley","qty":0,"unit":"","cat":"veg","text":"Garnish"}],"steps":["Place beans in a large pot and cover with cold water. Soak for at least 4 hours or overnight. Drain and rinse, before you use in the soup.","Chop one of the onions and leave the other one whole. Chop carrots.","Heat oil on a large pot over medium heat. Add the onion and carrots. Cook for 2 minutes. Add beans, water, peppers, head of onion, salt, pepper, summer savory, mint, thyme, Vegeta and tomato puree. Stir, bring to a boil, then reduce to a simmer and cook for 2 hours, or until the beans are tender.","Remove the peppers and whole onion. Mash the onion. Peel peppers and chop. Return to the pot.","Add more salt and pepper, if needed. Garnish with chopped parsley. Serve."],"source":"TheMealDB","sourceUrl":"https://cookinglsl.com/bulgarian-white-bean-soup/","time":135,"cost":1,"tags":["money","mealprep","protein","healthy"]},{"id":"mdb-53546","title":"Black Bean soup","image":"https://www.themealdb.com/images/media/meals/x0mreq1784577446.jpg","desc":"Starter","category":"Starter","serves":4,"diet":"meat","pork":false,"allergens":["dairy"],"base":"none","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"red onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"jalapeno","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"tomato purée","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"cumin","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"chilli powder","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"black beans","qty":3,"unit":"tin","cat":"pantry","text":""},{"name":"chicken stock","qty":3,"unit":"cup","cat":"pantry","text":""},{"name":"bay leaf","qty":1,"unit":"","cat":"pantry","text":""},{"name":"sour cream","qty":0,"unit":"","cat":"dairy","text":"Garnish"},{"name":"avocado","qty":0,"unit":"","cat":"veg","text":"Garnish"},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Garnish"},{"name":"lime","qty":0,"unit":"","cat":"veg","text":"To serve"}],"steps":["In a large pot over medium heat, heat oil. Add onion and cook until soft and translucent, about 5 minutes. Add jalapeños and garlic and cook until fragrant, about 2 minutes. Add tomato paste, stir to coat vegetables, and cook about a minute more. Season with salt, pepper, cumin, and chili powder and stir to coat.","Add black beans and broth. Stir soup, add bay leaf, and bring to a boil. Immediately reduce to a simmer and let simmer until slightly reduced and thickened, 15 to 20 minutes. (If a thinner soup is desired, add more broth as needed.)","Remove bay leaf and let cool slightly. Using an immersion blender or food processor, blend soup to desired consistency.","Serve with a dollop of sour cream, sliced avocado, and cilantro."],"source":"TheMealDB","sourceUrl":"https://www.delish.com/cooking/recipe-ideas/a55504/easy-black-bean-soup-recipe/","time":40,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-53047","title":"Moroccan Carrot Soup","image":"https://www.themealdb.com/images/media/meals/jcr46d1614763831.jpg","desc":"Moroccan · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"carrot","qty":6,"unit":"","cat":"veg","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":4,"unit":"","cat":"veg","text":""},{"name":"cumin","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"coriander","qty":0.5,"unit":"tsp","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garam masala","qty":0.25,"unit":"tsp","cat":"pantry","text":""},{"name":"lemon","qty":1,"unit":"tsp","cat":"veg","text":""}],"steps":["Preheat oven to 180° C.","Combine carrots, onion, garlic, cumin seeds, coriander seeds, salt and olive oil in a bowl and mix well. Transfer on a baking tray.","Put the baking tray in preheated oven and roast for 10-12 minutes or till carrots soften. Remove from heat and cool.","Grind the baked carrot mixture along with some water to make a smooth paste and strain in a bowl.","Heat the carrot mixture in a non-stick pan. Add two cups of water and bring to a boil. Add garam masala powder and mix. Add salt and mix well.","Remove from heat, add lemon juice and mix well.","Serve hot."],"source":"TheMealDB","sourceUrl":"https://www.sanjeevkapoor.com/Recipe/Moroccan-Carrot-Soup.html","time":25,"cost":1,"tags":["money","quick","mealprep","healthy"]},{"id":"mdb-52908","title":"Ratatouille","image":"https://www.themealdb.com/images/media/meals/wrpwuu1511786491.jpg","desc":"France · Vegetarian","category":"Vegetarian","serves":4,"diet":"vegan","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"aubergine","qty":2,"unit":"","cat":"veg","text":""},{"name":"courgette","qty":4,"unit":"","cat":"veg","text":""},{"name":"yellow pepper","qty":2,"unit":"","cat":"veg","text":""},{"name":"tomato","qty":4,"unit":"","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"Bunch"},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":3,"unit":"","cat":"veg","text":""},{"name":"red wine vinegar","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"sugar","qty":1,"unit":"tsp","cat":"pantry","text":""}],"steps":["Cut the aubergines in half lengthways. Place them on the board, cut side down, slice in half lengthways again and then across into 1.5cm chunks. Cut off the courgettes ends, then across into 1.5cm slices. Peel the peppers from stalk to bottom. Hold upright, cut around the stalk, then cut into 3 pieces. Cut away any membrane, then chop into bite-size chunks.","Score a small cross on the base of each tomato, then put them into a heatproof bowl. Pour boiling water over the tomatoes, leave for 20 secs, then remove. Pour the water away, replace the tomatoes and cover with cold water. Leave to cool, then peel the skin away. Quarter the tomatoes, scrape away the seeds with a spoon, then roughly chop the flesh.","Set a sauté pan over medium heat and when hot, pour in 2 tbsp olive oil. Brown the aubergines for 5 mins on each side until the pieces are soft. Set them aside and fry the courgettes in another tbsp oil for 5 mins, until golden on both sides. Repeat with the peppers. Don’t overcook the vegetables at this stage, as they have some more cooking left in the next step.","Tear up the basil leaves and set aside. Cook the onion in the pan for 5 mins. Add the garlic and fry for a further min. Stir in the vinegar and sugar, then tip in the tomatoes and half the basil. Return the vegetables to the pan with some salt and pepper and cook for 5 mins. Serve with basil."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/2903/ratatouille","time":35,"cost":1,"tags":["money","healthy"]},{"id":"mdb-53166","title":"Chickpea, chorizo & spinach stew","image":"https://www.themealdb.com/images/media/meals/xvnx8j1763287209.jpg","desc":"Spanish · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":[],"base":"none","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"onion","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":1,"unit":"","cat":"veg","text":""},{"name":"celery","qty":1,"unit":"","cat":"veg","text":""},{"name":"thyme","qty":3,"unit":"","cat":"veg","text":""},{"name":"bay leaf","qty":2,"unit":"","cat":"pantry","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"chorizo","qty":200,"unit":"g","cat":"meat","text":""},{"name":"cinnamon","qty":0.25,"unit":"tsp","cat":"pantry","text":""},{"name":"paprika","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"chickpeas","qty":800,"unit":"g","cat":"pantry","text":""},{"name":"sherry vinegar","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"spinach","qty":400,"unit":"g","cat":"veg","text":""}],"steps":["Heat the oil in a large pan, then gently fry the onion for 3-4 mins until it begins to soften. Stir in the carrot, celery, thyme and bay leaves. Season, then cook for 2-3 mins, stirring occasionally. Add the garlic, chorizo, cinnamon and smoked paprika. Gently fry until the vegetables soften and the chorizo starts to release its oils and crisp up.","Stir in the chickpeas, vinegar and 150ml water, then bring to a simmer for 1-2 mins until the chickpeas have heated up. Add the spinach, then stir through the chickpeas until it wilts a little. Remove from the heat, season to taste, then serve warm with crusty bread."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/chickpea-chorizo-spinach-stew","time":60,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52940","title":"Brown Stew Chicken","image":"https://www.themealdb.com/images/media/meals/sypxpx1515365095.jpg","desc":"Jamaican · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","soy"],"base":"none","ingredients":[{"name":"chicken","qty":1,"unit":"","cat":"meat","text":""},{"name":"tomato","qty":1,"unit":"","cat":"veg","text":""},{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":2,"unit":"","cat":"veg","text":""},{"name":"red pepper","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":1,"unit":"","cat":"veg","text":""},{"name":"lime","qty":1,"unit":"","cat":"veg","text":""},{"name":"thyme","qty":2,"unit":"tsp","cat":"veg","text":""},{"name":"allspice","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"soy sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"cornstarch","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"coconut milk","qty":2,"unit":"cup","cat":"pantry","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""}],"steps":["Squeeze lime over chicken and rub well. Drain off excess lime juice.","Combine tomato, scallion, onion, garlic, pepper, thyme, pimento and soy sauce in a large bowl with the chicken pieces. Cover and marinate at least one hour.","Heat oil in a dutch pot or large saucepan. Shake off the seasonings as you remove each piece of chicken from the marinade. Reserve the marinade for sauce.","Lightly brown the chicken a few pieces at a time in very hot oil. Place browned chicken pieces on a plate to rest while you brown the remaining pieces.","Drain off excess oil and return the chicken to the pan. Pour the marinade over the chicken and add the carrots. Stir and cook over medium heat for 10 minutes.","Mix flour and coconut milk and add to stew, stirring constantly. Turn heat down to minimum and cook another 20 minutes or until tender."],"source":"TheMealDB","sourceUrl":"http://www.geniuskitchen.com/recipe/authentic-jamaican-brown-stew-chicken-347996","time":60,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52773","title":"Honey Teriyaki Salmon","image":"https://www.themealdb.com/images/media/meals/xxyupu1468262513.jpg","desc":"Japanese · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["gluten","fish","soy","sesame"],"base":"none","ingredients":[{"name":"salmon","qty":454,"unit":"g","cat":"fish","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"soy sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"sake","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"sesame seed","qty":4,"unit":"tbsp","cat":"pantry","text":""}],"steps":["Mix all the ingredients in the Honey Teriyaki Glaze together. Whisk to blend well. Combine the salmon and the Glaze together.","Heat up a skillet on medium-low heat. Add the oil, Pan-fry the salmon on both sides until it’s completely cooked inside and the glaze thickens.","Garnish with sesame and serve immediately."],"source":"TheMealDB","sourceUrl":"https://www.themealdb.com/meal/52773","time":15,"cost":2,"tags":["quick","protein"]},{"id":"mdb-52959","title":"Baked salmon with fennel & tomatoes","image":"https://www.themealdb.com/images/media/meals/1548772327.jpg","desc":"British · Seafood","category":"Seafood","serves":4,"diet":"pescatarian","pork":false,"allergens":["fish"],"base":"none","ingredients":[{"name":"fennel","qty":2,"unit":"","cat":"veg","text":""},{"name":"parsley","qty":2,"unit":"tbsp","cat":"veg","text":""},{"name":"lemon","qty":0,"unit":"","cat":"veg","text":"Juice of 1"},{"name":"cherry tomato","qty":175,"unit":"g","cat":"veg","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"salmon","qty":350,"unit":"g","cat":"fish","text":""},{"name":"black olive","qty":0,"unit":"","cat":"pantry","text":"to serve"}],"steps":["Heat oven to 180C/fan 160C/gas 4. Trim the fronds from the fennel and set aside. Cut the fennel bulbs in half, then cut each half into 3 wedges. Cook in boiling salted water for 10 mins, then drain well. Chop the fennel fronds roughly, then mix with the parsley and lemon zest.","Spread the drained fennel over a shallow ovenproof dish, then add the tomatoes. Drizzle with olive oil, then bake for 10 mins. Nestle the salmon among the veg, sprinkle with lemon juice, then bake 15 mins more until the fish is just cooked. Scatter over the parsley and serve."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/7745/baked-salmon-with-fennel-and-tomatoes","time":50,"cost":2,"tags":["mealprep","family","protein","healthy"]},{"id":"mdb-53366","title":"Beef and Broccoli Stir-Fry","image":"https://www.themealdb.com/images/media/meals/m0p0j81765568742.jpg","desc":"Chinese · Beef","category":"Beef","serves":4,"diet":"meat","pork":false,"allergens":["gluten","shellfish","soy"],"base":"none","ingredients":[{"name":"soy sauce","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"dry sherry","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"cornstarch","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"tsp","cat":"staple","text":""},{"name":"sirloin steak","qty":454,"unit":"g","cat":"meat","text":""},{"name":"oyster sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"dry sherry","qty":1,"unit":"tsp","cat":"pantry","text":""},{"name":"soy sauce","qty":1,"unit":"tbsp","cat":"pantry","text":""},{"name":"chicken stock","qty":0.25,"unit":"cup","cat":"pantry","text":""},{"name":"broccoli","qty":454,"unit":"g","cat":"veg","text":""},{"name":"high heat cooking oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"garlic","qty":2,"unit":"clove","cat":"veg","text":""},{"name":"cornstarch","qty":1,"unit":"tsp","cat":"pantry","text":""}],"steps":["Marinate the beef:","Stir together the beef marinade ingredients (1 teaspoon soy sauce, 1 teaspoon Chinese rice wine, 1/2 teaspoon cornstarch, 1/8 teaspoon black pepper) in a medium bowl.","Add the beef slices and stir until coated. Let stand for 10 minutes.","Prepare the sauce:","Stir together the sauce ingredients (2 tablespoons oyster sauce, 1 teaspoon Chinese rice wine, 1 teaspoon soy sauce, 1/4 cup chicken broth) in a small bowl. Set aside.","Blanch or steam the broccoli:","Bring a pot of water to a boil. Add the broccoli and cook until crisp-tender, about 2 minutes. Drain thoroughly.","Stir-fry the beef:","Heat a large frying pan or wok over high heat until a bead of water sizzles and instantly evaporates upon contact. Add the cooking oil and swirl to coat.","Add the beef and immediately spread it out all over the surface of the wok or pan in a single layer (preferably not touching).","Let the beef fry undisturbed for 1 minute. Flip the beef slices over, add the garlic to the pan, and fry for an additional 30 seconds to 1 minute until no longer pink.","Add the sauce, cornstarch, and broccoli:","Pour in the sauce and the cornstarch slurry (1 teaspoon cornstarch dissolved in 1 tablespoon of water). Stir until the sauce boils and thickens, about 30 seconds. Stir in the broccoli.","Serve immediately, with steamed rice or on its own."],"source":"TheMealDB","sourceUrl":"https://www.simplyrecipes.com/recipes/broccoli_beef/","time":30,"cost":3,"tags":["quick","protein"]},{"id":"mdb-53201","title":"Stir-fried chicken with chillies & basil","image":"https://www.themealdb.com/images/media/meals/el64dy1763483009.jpg","desc":"Thai · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["gluten","fish","soy"],"base":"none","ingredients":[{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"chicken","qty":450,"unit":"g","cat":"meat","text":""},{"name":"garlic","qty":3,"unit":"tbsp","cat":"veg","text":""},{"name":"shallot","qty":3,"unit":"tbsp","cat":"veg","text":""},{"name":"chilli","qty":3,"unit":"","cat":"veg","text":""},{"name":"fish sauce","qty":2,"unit":"tbsp","cat":"pantry","text":""},{"name":"soy sauce","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"sugar","qty":2,"unit":"tsp","cat":"pantry","text":""},{"name":"basil","qty":0,"unit":"","cat":"veg","text":"Handful"}],"steps":["Heat a wok or large frying pan until it is very hot, then add 1 tbsp of the oil. When it is very hot, add the chicken and stir-fry over a high heat for 8-10 minutes, until browned all over. Using a slotted spoon, take the chicken from the pan and set aside.","Reheat the wok and add the remaining oil. Toss in the garlic and shallots and stir fry for 3 minutes, until golden brown.","Return the chicken to the wok and add the chillies, fish sauce, dark soy sauce and sugar. Stir fry over a high heat for a further 8-10 minutes or until the chicken is cooked through. Stir in the basil leaves and serve at once."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/ken-homs-stir-fried-chicken-chillies-basil","time":35,"cost":1,"tags":["money","mealprep","protein","healthy"]},{"id":"mdb-52851","title":"Nutty Chicken Curry","image":"https://www.themealdb.com/images/media/meals/yxsurp1511304301.jpg","desc":"India · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["dairy","peanuts"],"base":"none","ingredients":[{"name":"chilli","qty":1,"unit":"","cat":"veg","text":""},{"name":"ginger","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":1,"unit":"","cat":"veg","text":""},{"name":"coriander","qty":0,"unit":"","cat":"veg","text":"Bunch"},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"chicken breast","qty":4,"unit":"","cat":"meat","text":""},{"name":"peanut butter","qty":5,"unit":"tbsp","cat":"pantry","text":""},{"name":"chicken stock","qty":150,"unit":"ml","cat":"pantry","text":""},{"name":"greek yogurt","qty":200,"unit":"g","cat":"dairy","text":""}],"steps":["Finely slice a quarter of the chilli, then put the rest in a food processor with the ginger, garlic, coriander stalks and one-third of the leaves. Whizz to a rough paste with a splash of water if needed.","Heat the oil in a frying pan, then quickly brown the chicken chunks for 1 min. Stir in the paste for another min, then add the peanut butter, stock and yogurt. When the sauce is gently bubbling, cook for 10 mins until the chicken is just cooked through and sauce thickened. Stir in most of the remaining coriander, then scatter the rest on top with the chilli, if using. Eat with rice or mashed sweet potato."],"source":"TheMealDB","sourceUrl":"https://www.bbcgoodfood.com/recipes/11753/nutty-chicken-curry","time":25,"cost":1,"tags":["money","quick","mealprep","protein","healthy"]},{"id":"mdb-52806","title":"Tandoori chicken","image":"https://www.themealdb.com/images/media/meals/qptpvt1487339892.jpg","desc":"India · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":["dairy"],"base":"none","ingredients":[{"name":"lemon","qty":2,"unit":"","cat":"veg","text":""},{"name":"paprika","qty":4,"unit":"tsp","cat":"pantry","text":""},{"name":"red onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"chicken thigh","qty":16,"unit":"","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"greek yogurt","qty":300,"unit":"ml","cat":"dairy","text":""},{"name":"ginger","qty":0,"unit":"","cat":"veg","text":"large piece"},{"name":"garlic","qty":4,"unit":"","cat":"veg","text":""},{"name":"garam masala","qty":0.75,"unit":"tsp","cat":"pantry","text":""},{"name":"cumin","qty":0.75,"unit":"tsp","cat":"pantry","text":""},{"name":"chilli powder","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"turmeric","qty":0.25,"unit":"tsp","cat":"pantry","text":""}],"steps":["Mix the lemon juice with the paprika and red onions in a large shallow dish. Slash each chicken thigh three times, then turn them in the juice and set aside for 10 mins.","Mix all of the marinade ingredients together and pour over the chicken. Give everything a good mix, then cover and chill for at least 1 hr. This can be done up to a day in advance.","Heat the grill. Lift the chicken pieces onto a rack over a baking tray. Brush over a little oil and grill for 8 mins on each side or until lightly charred and completely cooked through."],"source":"TheMealDB","sourceUrl":"http://www.bbcgoodfood.com/recipes/1660651/tandoori-chicken","time":35,"cost":2,"tags":["protein","healthy"]},{"id":"mdb-53287","title":"Tajine de Poulet aux Carottes et Patates Douces (Chicken and Sweet Potato Tagine)","image":"https://www.themealdb.com/images/media/meals/d8bfyg1764117503.jpg","desc":"Algerian · Chicken","category":"Chicken","serves":4,"diet":"meat","pork":false,"allergens":[],"base":"none","ingredients":[{"name":"onion","qty":2,"unit":"","cat":"veg","text":""},{"name":"celery","qty":2,"unit":"","cat":"veg","text":""},{"name":"coriander","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"parsley","qty":0.5,"unit":"","cat":"veg","text":""},{"name":"turmeric","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"cumin","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"paprika","qty":0.5,"unit":"tsp","cat":"pantry","text":""},{"name":"ground ginger","qty":0.25,"unit":"tsp","cat":"pantry","text":""},{"name":"cayenne pepper","qty":0.25,"unit":"tsp","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"chicken thigh","qty":4,"unit":"","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"","cat":"staple","text":""},{"name":"raisin","qty":0.25,"unit":"cup","cat":"pantry","text":""},{"name":"chicken stock","qty":1,"unit":"cup","cat":"pantry","text":""},{"name":"sweet potato","qty":1,"unit":"","cat":"veg","text":""},{"name":"carrot","qty":3,"unit":"","cat":"veg","text":""},{"name":"prune","qty":0.25,"unit":"cup","cat":"pantry","text":""}],"steps":["Combine onions, celery, cilantro, and parsley in a large pot. Stir in turmeric, cumin, paprika, ginger, cayenne pepper, salt, and pepper. Place chicken thighs on top. Drizzle olive oil over chicken. Cover and simmer over low heat until chicken is tender, about 40 minutes.","Place raisins in a small bowl and cover with hot water; let soak for 10 minutes. Drain.","Preheat oven to 400 degrees F (200 degrees C).","Transfer chicken mixture into an oven-safe tagine or casserole dish. Add sweet potato and carrots. Cover with lid or aluminum foil.","Bake in the preheated oven until sweet potato is soft, about 40 minutes. Add drained raisins and prunes. Continue baking, covered, until raisins and prunes are heated through, about 10 minutes."],"source":"TheMealDB","sourceUrl":"https://www.allrecipes.com/recipe/258873/tajine-de-poulet-aux-carottes-et-patates-douces-chicken-and-sweet-potato-tagine/","time":105,"cost":2,"tags":["mealprep","protein","healthy"]},{"id":"mdb-52999","title":"Crispy Sausages and Greens","image":"https://www.themealdb.com/images/media/meals/st1ifa1583267248.jpg","desc":"Irish · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":[],"base":"none","ingredients":[{"name":"kale","qty":1,"unit":"","cat":"veg","text":""},{"name":"italian fennel sausage","qty":8,"unit":"","cat":"meat","text":""},{"name":"cabbage","qty":1,"unit":"","cat":"veg","text":""},{"name":"garlic","qty":8,"unit":"","cat":"veg","text":""},{"name":"onion","qty":0,"unit":"","cat":"veg","text":"Sliced"},{"name":"shiitake mushroom","qty":0,"unit":"","cat":"veg","text":"Sliced"},{"name":"chicken stock","qty":1,"unit":"cup","cat":"pantry","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""},{"name":"salt & pepper","qty":0,"unit":"","cat":"staple","text":""}],"steps":["Preheat the oven to 350°. Remove the stems from one bunch of Tuscan kale and tear the leaves into 1\" pieces (mustard greens, collards, spinach, and chard are great, too). Coarsely chop half a head of green cabbage. Combine the greens in a large baking dish and add 4 cloves of thinly sliced garlic. Adding some sliced onions and shiitake mushrooms at this point is optional, but highly recommended (I'll sauté the onions and mushrooms in a cast iron baking dish right on the stove before adding to the greens). Coat the greens with some olive oil and pour ½ cup chicken stock or broth over everything. Cover the dish with foil and bake until the greens are wilted, about 15 minutes. Remove foil and season with salt and pepper. Continue to bake until cabbage is tender, about 20-25 minutes more.","Meanwhile, heat a little olive oil in a large skillet over medium-high. Prick four sweet Italian sausages with a fork and cook until browned on all sides and cooked through, 10 to 12 minutes. When the greens are done, slice the sausage and toss into the greens with a splash of your favorite vinegar (I like sherry or red wine)."],"source":"TheMealDB","sourceUrl":"https://www.bonappetit.com/columns/cooking-without-recipes/article/kale-cabbage-sausage-weeknight-dinner","time":65,"cost":1,"tags":["money","family","protein","healthy"]},{"id":"mdb-52822","title":"Toad In The Hole","image":"https://www.themealdb.com/images/media/meals/ytuvwr1503070420.jpg","desc":"British · Pork","category":"Pork","serves":4,"diet":"meat","pork":true,"allergens":["gluten","dairy","egg"],"base":"none","ingredients":[{"name":"sausage","qty":8,"unit":"","cat":"meat","text":""},{"name":"oil","qty":0,"unit":"tbsp","cat":"staple","text":""},{"name":"plain flour","qty":100,"unit":"g","cat":"pantry","text":""},{"name":"egg","qty":2,"unit":"","cat":"dairy","text":""},{"name":"horseradish","qty":1,"unit":"tbsp","cat":"veg","text":""},{"name":"milk","qty":225,"unit":"ml","cat":"dairy","text":""},{"name":"cherry tomato","qty":200,"unit":"g","cat":"veg","text":""}],"steps":["Preheat the oven to 200°C/fan180°C/gas 6. fry sausages in a non-stick pan until browned.","Drizzle vegetable oil in a 30cm x 25cm x 6cm deep roasting tray and heat in the oven for 5 minutes.","Put the plain flour in a bowl, crack in the medium free-range eggs, then stir in the grated horseradish. Gradually beat in the semi-skimmed milk. Season.","Put the sausages into the hot roasting tray and pour over the batter. Top with cherry tomatoes on the vine and cook for 30 minutes until puffed and golden."],"source":"TheMealDB","sourceUrl":"http://www.deliciousmagazine.co.uk/recipes/georgina-fuggles-horseradish-and-vine-tomato-toad-in-the-hole/","time":50,"cost":1,"tags":["money","protein"]}];
